INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_9b198152cd03c5c299b3119f","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",22,"Seite 14","DB Netz AG\n\nBauartverantwortung\n\nLastenheft-Entwicklung und ETCS-Fahrzeugtechnik\n\nI.NAI 4521\n\nVÃ¶lckerstr. 5\n\nGemÃ¤ÃŸ Verteiler Ril 483.0701\n\n80939 MÃ¼nchen\n\nwww.dbnetze.com/fahrweg\n\nPhilipp Pinter\n\nTel.: 089 1308-5234\n\nMobil: 0160 97258041\n\n[E-Mail-Adresse entfernt]\n\nZeichen: I.NAI 4521 Pi\n\n15.06.2022\n\nAusnahme 104 Aktualisierung 01 zur Richtlinie 483.0701 â€žETCS-Fahrzeugeinrichtungen\n\nbedienenâ€œ\n\nSehr geehrte Damen und Herren,\n\nmit der Ausnahme 104 Aktualisierung 01 zur Richtlinie 483.0701 werden die nachfolgend aufgefÃ¼hrten Regeln zum Bedienen der ETCS-Fahrzeugeinrichtung in den entsprechenden Abschnitten der Richtlinie sowie in den AnhÃ¤ngen geÃ¤ndert bzw. neu aufgenommen und zum 11.12.2022\n\nin Kraft gesetzt.\n\nDie Ausnahme 104 Aktualisierung 01 zur Richtlinie 483.0701 ersetzt die Ausnahme 104.\n\n...\n\nDB Netz AG Vorsitzender des Vorstand: Jens Bergmann\n\nSitz Frankfurt am Main Aufsichtsrates: Frank Sennhenn, Dr. Christian GruÃŸ\n\nRegistergericht Ronald Pofalla Vorsitzender Dr. Volker Hentschel\n\nFrankfurt am Main Ute Plambeck\n\nHRB 50 879 Dr. Christian Runzheimer\n\nUSt-IdNr.: DE199861757\n\nNÃ¤here Informationen zur Datenverarbeitung im DB-Konzern finden Sie hier: www.deutschebahn.com/datenschutz",146,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":14,\"source_id\":\"src_d87848f5dd80f