INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_ad0fdfe945a4e1115e3c986c","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",42,"Seite 27","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n27/98\n\nAbsatz (17 ehemals 15) â€žLÃ¶schen der Release Speedâ€œ:\n\nIn der Beschreibung wurde prÃ¤zisiert, an welchen Sperrsignalen (siehe Auflistung in den ErlÃ¤uterungen bei Abschnitt 4 (14)) die Release Speed gelÃ¶scht wird. Des Weiteren wurde ergÃ¤nzt,\n\ndass die Release Speed auch am Signal Ne 1 gelÃ¶scht wird.\n\nAbschnitt 13 â€žRegelbetriebâ€œ Absatz (21) ehemals (19) â€ž\"Override\" aktivâ€œ:\n\nIm Hinweis wurde geÃ¤ndert, dass die Geschwindigkeit, ab der Sie Override bereits wÃ¤hrend der\n\nFahrt aktivieren kÃ¶nnen, abhÃ¤ngig von der ETCS-StreckenausrÃ¼stung ist. Auf Strecken mit\n\nETCS-Level 1 bei kleiner/gleich 20 km/h und auf Strecken mit ETCS-Level bei kleiner/gleich\n\n40 km/h.\n\nAbschnitt 13 â€žRegelbetriebâ€œ Unterabschnitt â€žFahrt in der ETCS-Betriebsart SRâ€œ:\n\nAbsatz (23) ehemals (21) â€žÃœberwachungsgrÃ¶ÃŸen in der ETCS-Betriebsart SR einblendenâ€œ:\n\nIn der Beschreibung wurde geÃ¤ndert, dass die vom ETCS-FzG Ã¼berwachte zulÃ¤ssige Geschwindigkeit abhÃ¤ngig von der ETCS-StreckenausrÃ¼stung ist. Auf Strecken mit ETCS-Level 1 wird auf\n\n20 km/h und auf Strecken mit ETCS-Level 2 wird auf 40 km/h Ã¼berwacht.\n\nAbsatz (22) â€žWechsel in die ETCS-Betriebsart LSâ€œ:\n\nDer Absatz wurde verschoben unter den neu aufgenommenen Unterabschnitt â€žWechsel von der\n\nETCS-Betriebsart SR in die ETCS-Betriebsart LSâ€œ. Der neue Unterabschnitt steht nach dem Unterabschnitt â€žHalt in der ETCS-Betriebsart SRâ€œ.\n\nAbschnitt 13 â€žRegelbetriebâ€œ Unterabschnitt â€žHalt in der ETCS-Betriebsart SRâ€œ:\n\nAbsatz (24) ehemals (23) â€žAnzeige Sollgeschwindigkeitâ€œ:\n\nIn der Beschreibung wurde geÃ¤ndert, dass die angezeigte Sollgeschwindigkeit abhÃ¤ngig von der\n\nETCS-StreckenausrÃ¼stung ist. Auf Strecken mit ETCS-Level 1 wird 20 km/h und auf Strecken mit\n\nETCS-Level 2 wird 40 km/h angezeigt.",242,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":27,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","cf4d205d0e00543e5f7450bbd33fb3fc1af1e7406bca5b8c2b5e74f660d8d7bb"],["chunk_97d4c1ebe79f3d3ed79ea2f7","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",43,"Seite 27","Abschnitt 13 â€žRegelbetriebâ€œ Unterabschnitt â€žWechsel von der ETCS-Betriebsart SR in die\n\nETCS-Betriebsart LSâ€œ:\n\nAbsatz (25) ehemals (22) â€žWechsel in die ETCS-Betriebsart LSâ€œ:\n\nDer Absatz wurde unter den neu aufgenommenen Unterabschnitt â€žWechsel von der ETCS-Betriebsart SR in die ETCS-Betriebsart LSâ€œ verschoben, die Beschreibung prÃ¤zisiert und in der AufzÃ¤hlung um den Wechsel an der Aufwertebalise, die 250 m vor bestimmten Signalen liegen kann,\n\nergÃ¤nzt. Diese Signale sind Hauptsignale, Sperrsignale (siehe Auflistung in den ErlÃ¤uterungen\n\nbei Abschnitt 4 (14)) oder das Signal Ne 1.\n\nIn den Bildern 60 und 61 wurde ergÃ¤nzt, dass diese nur fÃ¼r ETCS-Level 2 gelten, da die angezeigte ÃœberwachungsgrÃ¶ÃŸe V = 40 km/h anzeigt.\n\nsoll\n\nAbschnitt 14 â€žAutomatischer Levelwechselâ€œ Unterabschnitt â€žAutomatischer Levelwechsel\n\nvon ETCS-Level 1 nach ETCS-Level NTC PZB/LZBâ€œ Absatz (30) â€žOrtâ€œ:\n\nErgÃ¤nzt wurde, dass der Levelwechsel auch am oder nach dem Grenzsignal stattfinden kann,\n\nwenn es sich hierbei um ein Hauptsignal mit Vorsignalfunktion oder um ein Hauptsignal, an dem\n\nsich ein Vorsignal befindet, handelt. Der Ort des Levelwechsel ist abhÃ¤ngig von der Stellung des\n\nHauptsignals.",167,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":27,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","e493d75075752a61c184e3c07eaec6e95f6395b9cd9350be2b0dafab4d636c4c"],["chunk_6eacde13a53493e4db524973","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",44,"Seite 28","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n28/98\n\nAbschnitt 14 â€žAutomatischer Levelwechselâ€œ Unterabschnitt â€žAutomatischer Levelwechsel\n\nvon ETCS-Level 2 nach ETCS-Level 1â€œ Absatz (48) â€žAnkÃ¼ndigungâ€œ:\n\nIn der Beschreibung wurde die Situation einer Geschwindigkeitsrestriktion in dem Bereich, vor\n\ndem der Levelwechsel stattfinden soll, ergÃ¤nzt. Dann sendet die ETCS-Zentrale abhÃ¤ngig davon,\n\nan welchem Ort die Geschwindigkeitsrestriktion endet, eine der aufgefÃ¼hrten Textmeldungen,\n\nwelche den Tf an die Einhaltung der Geschwindigkeitsrestriktion fÃ¼r die gesamte ZuglÃ¤nge erinnern soll.\n\nAbschnitt 14 â€žAutomatischer Levelwechselâ€œ Unterabschnitt â€žAutomatischer Levelwechsel\n\nvon ETCS-Level 2 nach ETCS-Level 1â€œ Absatz (52) â€žZugfahrt mit besonderem Auftragâ€œ:\n\nDie Beschreibung wurde geÃ¤ndert, dass bei der Zugfahrt mit besonderem Auftrag beim Vorbeifahren am Grenzsignal der automatische Levelwechsel nach ETCS-Level 1 nicht am Grenzsignal, sondern an einer nachfolgenden Balise stattfindet.\n\n483.0701A01 Ãœbersicht der ETCS-Textmeldungen:\n\nAbschnitt 1 Textmeldungen auf Strecken mit ETCS-Level 1:\n\nDie bestehenden Textmeldungen wurden teilweise prÃ¤zisiert. Des weiteren wurden neue Textmeldungen aufgenommen, die auf ETCS-Level 1 Strecken angezeigt werden kÃ¶nnen.\n\nAbschnitt 2 Textmeldungen auf Strecken mit ETCS-Level 2:\n\nDie aufgelisteten Textmeldungen wurde prÃ¤zisiert bzw. korrigiert und um zwei neue Textmeldungen ergÃ¤nzt, die auf ETCS-Level 2 Strecken angezeigt werden kÃ¶nnen.\n\nMit freundlichen GrÃ¼ÃŸen\n\nDB Netz AG\n\ngez. i. V. Schmidtke gez. i. A. Pinter\n\nLeiter I.NAI 4521 I.NAI 4521\n\n(Fachautor Ril 483.0701)",204,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":28,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","ac9cc839d0c9ff5f569550bdcfc080a57c13b6711ee9f724f5d3e43ad5f77980"],["chunk_e22e1bbce20d9f68a6f0ad51","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",45,"Seite 29","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n29/98\n\nRil 483.0701\n\nIn Abschnitt 1 â€žGeltungsbereichâ€œ ist der Absatz (1) durch\n\nden folgenden zu ersetzen:\n\n(1) Diese Richtlinie gilt fÃ¼r Eisenbahnverkehrsunternehmen, die Geltungsbereich\n\nFahrzeuge unter Ãœberwachung von ETCS auf den Schienenwegen der DB InfraGO AG verkehren lassen.\n\nIn Abschnitt 1 â€žGeltungsbereichâ€œ ist der Absatz (2) durch\n\nden folgenden zu ersetzen:\n\n(2) Die Richtlinie beschreibt das Bedienen der ETCS-Fahrzeugein- Inhalt\n\nrichtung sowie deren wesentliche Bestandteile.\n\nBaureihen-/bauartspezifische Abweichungen sind in dieser\n\nRichtlinie durch â€žfahrzeugabhÃ¤ngigâ€œ gekennzeichnet. Sie sind in\n\nden Regeln fÃ¼r das Bedienen der Fahrzeuge enthalten.\n\nUnterschiede, die durch die ETCS-Fahrzeugsoftware (Systemversion des ETCS-FahrzeuggerÃ¤tes) bedingt sind, sind in dieser\n\nRichtlinie durch â€žabhÃ¤ngig von der ETCS-Fahrzeugsoftwareâ€œ\n\ngekennzeichnet.\n\nUnterschiede, die durch die ETCS-Streckensoftware (Systemversion der ETCS-StreckenausrÃ¼stung) bedingt sind, sind in dieser Richtlinie durch â€žabhÃ¤ngig von der ETCS-Streckensoftwareâ€œ\n\ngekennzeichnet.",132,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":29,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","94948b545c8641884f73db4a62b39b1e702abc160f3cef1feb37e6d0d1a31c6d"],["chunk_e1642b741aede6533811fa55","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",46,"Seite 30","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n30/98\n\nIn Abschnitt 3 â€žETCS-Levelâ€œ ist der Absatz (2) durch den\n\nfolgenden zu ersetzen:\n\nETCS-Level (2) In ETCS-Level NTC PZB/LZB in der ETCS-Betriebsart SN Ã¼ber-\n\nNTC PZB/LZB gibt das ETCS-FahrzeuggerÃ¤t (ETCS-FzG) die Ãœberwachung\n\nan die nationalen Zugbeeinflussungen PZB oder LZB. Diese erfassen die Beeinflussungen der PZB oder LZB-Streckeneinrichtungen und werten sie aus. In der ETCS-Betriebsart SN mÃ¼ssen\n\nSie nach den Regeln der jeweils wirksamen nationalen Zugbeeinflussung fahren.\n\nDas ETCS-FzG liest Balisen und kann z. B. eine Funkverbindung zur ETCS-Zentrale aufbauen.\n\nHinweise:\n\nDie nationalen Zugbeeinflussungen werden als National Train\n\nControl (NTC) bezeichnet.\n\nIm MFD kÃ¶nnen diese abhÃ¤ngig von der ETCS-Fahrzeugsoftware entweder mit STM oder mit NTC bezeichnet sein.",114,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":30,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","22b5aa3445179235af9ecfc5126dbb177d406dd4906c02a04c37fe9a5850bc24"],["chunk_34d0cff755a5c59d0a8444a1","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",47,"Seite 31","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n31/98\n\nIn Abschnitt 4 â€žETCS-Betriebsartenâ€œ ist der Absatz (4)\n\ndurch den folgenden zu ersetzen:\n\n(4) In der ETCS-Betriebsart LS (Limited Supervision) fahren die LS\n\nZÃ¼ge signalgefÃ¼hrt. Es werden keine FÃ¼hrungsgrÃ¶ÃŸen angezeigt, sondern â€“ abhÃ¤ngig von der betrieblichen Situation â€“ nur\n\ndie ÃœberwachungsgrÃ¶ÃŸen LSSMA oder Release Speed.\n\nETCS Ã¼bernimmt in der ETCS-Betriebsart LS die Aufgaben\n\neiner punktfÃ¶rmigen Zugbeeinflussung. Die Informationen werden mittels Balisen punktfÃ¶rmig an das ETCS-FzG Ã¼bertragen.\n\nDas ETCS-FzG Ã¼berwacht das Einhalten\n\na) der zulÃ¤ssigen HÃ¶chstgeschwindigkeit von 160 km/h.\n\nb) einer niedrigeren Geschwindigkeit, die sich durch\n\n- den Einstellwert VMZ (maximal zulÃ¤ssige Geschwindigkeit des Zuges),\n\n- die vorhandenen Brh (Bremshundertstel),\n\n- Langsamfahrstellen,\n\n- Geschwindigkeitssignalisierung am Vor- bzw. Hauptsignal oder\n\n- Ãœberwachungssignale, die einen Halt vor dem BÃœ\n\nvorschreiben,\n\nergeben kann.\n\nc) der LSSMA (siehe Abschnitt 7 Absatz (7)) nach Vorbeifahrt\n\n- am Signal mit der Signalbedeutung â€žHalt erwartenâ€œ\n\noder\n\n- am alleinstehenden Signal Ne 2.\n\nd) der Release Speed.\n\nDie ETCS-Betriebsart LS ist, abhÃ¤ngig von der ETCS-Fahrzeugsoftware, in ETCS-Level 1 verfÃ¼gbar.",168,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":31,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","c2324af91f0aaba29f85209c816d18e0f22729635f262bbda050e1a65cb9fb99"],["chunk_368bd33764782cf5597e6226","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",48,"Seite 32","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n32/98\n\nIn Abschnitt 4 â€žETCS-Betriebsartenâ€œ ist der Absatz (5)\n\ndurch den folgenden zu ersetzen:\n\nSR (5) Das ETCS-FzG wechselt in die ETCS-Betriebsart SR (Staff\n\nResponsible), nachdem Sie\n\n- â€žOverrideâ€œ und anschlieÃŸend â€žEOAâ€œ betÃ¤tigt haben oder\n\n- in ETCS-Level 1 oder ETCS-Level 2 die angekÃ¼ndigte\n\nETCS-Betriebsart SR bestÃ¤tigt haben.\n\nDas ETCS-FzG Ã¼berwacht\n\na) die Vorbeifahrt\n\n- in ETCS-Level 1 am Halt zeigenden oder gestÃ¶rten\n\nHaupt- bzw. Sperrsignal1 oder am Signal Ne 1 und\n\n- in ETCS-Level 2 am Signal Ne 14 und\n\nb) die zulÃ¤ssige Geschwindigkeit\n\n- von 20 km/h auf Strecken mit ETCS-Level 1 und\n\n- von 40 km/h auf Strecken mit ETCS-Level 2\n\noder ggf. eine niedrigere Geschwindigkeit (siehe Abschnitt\n\n13 Absatz (24) und (25)).\n\nHinweis:\n\nEine niedrigere Geschwindigkeit wird z. B. angezeigt,\n\nwenn die entsprechenden Balisen verlegt sind.\n\nDie ETCS-Betriebsart SR ist in ETCS-Level 1 und ETCS-\n\nLevel 2 verfÃ¼gbar.\n\n1 Sperrsignale am Gegengleis in HÃ¶he des Einfahrsignals, Sperrsignale,\n\ndie Ziel einer Zugfahrt sind und Sperrsignale vor Gruppensignalen",167,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":32,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","cffb103cc85e4b14699766438357898a58840c674f3a3d72c996dd5af12f08de"],["chunk_d31ea22a6106267f3bfd05a7","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",49,"Seite 33","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n33/98\n\nIn Abschnitt 4 â€žETCS-Betriebsartenâ€œ ist der Absatz (14)\n\ndurch den folgenden zu ersetzen:\n\n(14) Das ETCS-FzG wechselt in folgenden FÃ¤llen in die ETCS- TR\n\nBetriebsart TR (Trip) und leitet eine Zwangsbremsung bis zum\n\nStillstand ein:\n\na) Beim Levelwechsel von ETCS-Level NTC PZB/LZB nach\n\nETCS-Level 1 oder ETCS-Level 2 ist eine PZB-Zwangsbremsung infolge einer 2000 Hz Beeinflussung oder eine\n\nLZB-Zwangsbremsung infolge der Vorbeifahrt am LZB-Halt\n\nnoch wirksam.\n\nDas MFD zeigt die Textmeldung\n\n- â€žBremsanforderung durch PZBâ€œ oder\n\n- â€žBremsanforderung durch PZB/LZBâ€œ\n\nan.\n\nb) Beim Levelwechsel von ETCS-Level NTC PZB/LZB oder\n\nETCS-Level 0 nach\n\n- ETCS-Level 1 ohne Aufwertung durch eine Balise,\n\ndie eine Zustimmung zur Fahrt Ã¼bertrÃ¤gt oder\n\n- ETCS-Level 2 ohne gÃ¼ltige ETCS-Fahrterlaubnis.\n\nDas MFD zeigt die Textmeldung â€žFehlende ETCS-Fahrterlaubnis beim Levelwechselâ€œ an.\n\nHinweis:\n\nSystembedingt wird die Textmeldung auch in ETCS-\n\nLevel 1 in der ETCS-Betriebsart LS angezeigt.",146,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":33,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","4de72fe53746dc4ff12a7b83b04235294996e36e0f72f9be2322117407cbd1be"],["chunk_509e1a6845bd9cc15ce0b083","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",50,"Seite 34","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n34/98\n\nc) Bei der Vorbeifahrt in ETCS-Level 1\n\n- am Halt zeigenden oder gestÃ¶rten Haupt- bzw.\n\nSperrsignal2 oder\n\n- am Signal Ne 1.\n\nDas MFD zeigt die Textmeldung\n\n- â€žVorbeifahrt am ETCS-Haltâ€œ oder\n\n- â€žUnerlaubte Vorbeifahrt am EOA / LOAâ€œ\n\nan.\n\nHinweis:\n\nSystembedingt wird die Textmeldung auch in ETCS-Level 1 in der ETCS-Betriebsart LS angezeigt.\n\nd) Bei der Vorbeifahrt in ETCS-Level 2\n\n- am ETCS-Halt in den ETCS-Betriebsarten FS und\n\nOS und das MFD zeigt die Textmeldung\n\n- â€žVorbeifahrt am ETCS-Haltâ€œ oder\n\n- â€žUnerlaubte Vorbeifahrt am EOA / LOAâ€œ\n\nan oder\n\n- am Signal Ne 14 in der ETCS-Betriebsart SR und\n\ndas MFD zeigt die Textmeldung â€žHalt in SRâ€œ an.\n\ne) In ETCS-Level 1, wenn die LEU gestÃ¶rt ist und die Balise\n\ndas entsprechende StÃ¶rungstelegramm Ã¼bertragen hat.\n\nDas MFD zeigt die Textmeldung\n\n- â€žStÃ¶rung Hauptsignal-Baliseâ€œ oder\n\n- â€žStÃ¶rung Sperrsignal-Baliseâ€œ\n\nan.\n\nf) In ETCS-Level 1 und ETCS-Level 2 bei bestimmten\n\nBalisenlesefehlern.\n\nDas MFD zeigt die Textmeldung â€žBalisenlesefehlerâ€œ an.\n\n2 Sperrsignale am Gegengleis in HÃ¶he des Einfahrsignals, Sperrsignale,\n\ndie Ziel einer Zugfahrt sind und Sperrsignale vor Gruppensignalen",182,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":34,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","8b832d696b104a27ccb02e5b91af598745f28ab31da40a99fd576963ac98dc3e"],["chunk_6d039f54412b556441ea5863","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",51,"Seite 35","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n35/98\n\ng) In ETCS-Level 1 und ETCS-Level 2 beim Befahren einer\n\nBalise einer nicht kompatiblen Strecke, wenn die Systemversion des ETCS-FzG nicht kompatibel mit der Systemversion der ETCS-Streckeneinrichtung ist.\n\nDas MFD zeigt die Textmeldung â€žETCS-StreckenausrÃ¼stung nicht kompatibelâ€œ an.\n\nh) In ETCS-Level 2, wenn die ETCS-Zentrale einen ETCS-\n\nNothalt fÃ¼r den Zug gesendet hat.\n\nDas MFD zeigt die Textmeldung\n\n- â€žRÃ¼cknahme der ETCS-Fahrterlaubnisâ€œ oder\n\n- â€žETCS-Nothaltâ€œ\n\nan.\n\nErgÃ¤nzend kann, abhÃ¤ngig von der betrieblichen Situation,\n\ndie Textmeldung\n\n- â€žUnzulÃ¤ssige Bewegung, Nothaltauftrag geben!â€œ\n\noder\n\n- â€žUnzulÃ¤ssige Fahrzeugbewegung, Nothaltauftrag\n\ngeben!â€œ\n\nangezeigt werden.\n\nHinweis:\n\nDie Auflistung enthÃ¤lt nur die FÃ¤lle, die am hÃ¤ufigsten vorkommen kÃ¶nnen.\n\nDie ETCS-Betriebsart TR ist in ETCS-Level NTC PZB/LZB,\n\nETCS-Level 1, ETCS-Level 2 und abhÃ¤ngig von der ETCS-\n\nFahrzeugsoftware auch in ETCS-Level 0 verfÃ¼gbar.",130,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":35,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","6c224ff221ae761c0f64a17621281ddafbc7bfc459c9b2246fc66d4ed9f310fe"],["chunk_804185801685b5cfd4b8d580","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",52,"Seite 36","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n36/98\n\nIn Abschnitt 5 â€žETCS-Streckeneinrichtungenâ€œ ist der Absatz (2) durch den folgenden zu ersetzen:\n\nBalise (2) Eine Balise ist ein DatenÃ¼bertragungselement, das sich mittig im\n\nGleis befindet und Informationen in Form von Telegrammen\n\npunktfÃ¶rmig an das ETCS-FzG Ã¼bertrÃ¤gt.\n\nMehrere Balisen kÃ¶nnen zu einer Balisengruppe zusammengefasst sein, um z. B. die Fahrtrichtung eindeutig zuzuordnen bzw.\n\nmehrere Telegramme zu Ã¼bertragen.\n\nHinweis:\n\nZur Vereinfachung wird in dieser Richtlinie nur der Begriff\n\nâ€žBaliseâ€œ verwendet.\n\nSchaltbare Balisen Ã¼bertragen die in der Regel von einer LEU\n\ngesendeten spezifischen Telegramme z. B. Signalinformationen.\n\nNicht schaltbare Balisen Ã¼bertragen fest einprogrammierte\n\nTelegramme z. B. Ortungs- und Streckeninformationen.\n\nIn Abschnitt 5 â€žETCS-Streckeneinrichtungenâ€œ ist der Absatz (3) durch den folgenden zu ersetzen:\n\nEuroloop (3) Ein Euroloop (Leiterschleife) ist in ETCS-Level 1 eine optionale\n\nEinrichtung im Gleis, die Informationen entlang eines kurzen\n\nStreckenabschnittes (bis zu ca. 1 km) kontinuierlich an das\n\nFahrzeug Ã¼bertragen kann. Der Euroloop Ã¼bertrÃ¤gt die gleichen\n\nTelegramme wie eine Balise, jedoch keine Ortungsinformationen.\n\nDas Fahrzeug liest die Telegramme mit der Euroloopantenne\n\nbzw. einer kombinierten Antenne fÃ¼r Balisen und Euroloop.\n\nHinweis:\n\nAuf der Infrastruktur der DB InfraGO AG wird Euroloop nicht verwendet.\n\nIn Abschnitt 5 â€žETCS-Streckeneinrichtungenâ€œ ist der Absatz (4) durch den folgenden zu ersetzen:\n\nLEU (4) Die Lineside Electronic Unit (LEU) greift die Signalinformationen\n\nab und sendet fÃ¼r jeden Signalbegriff ein spezifisches Telegramm an die schaltbare Balise und/oder den Euroloop in\n\nETCS-Level 1.",231,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":36,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","0fe5f5d07f9d7bc368040105be78ec5373d548d88f9136f74a86bcaf68558a4f"],["chunk_236d6a03ceaac0c183e6a915","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",53,"Seite 37","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n37/98\n\nIn Abschnitt 6 â€žETCS-Fahrzeugeinrichtungâ€œ ist der Absatz (4) durch den folgenden zu ersetzen:\n\n(4) Die Balisenantenne liest die Telegramme aus den im Gleis ver- Balisen-/ Eurolegten Balisen. Beim Befahren versorgt sie die Balisen induktiv loopantenne\n\nmit der fÃ¼r das Ãœbertragen der Telegramme notwendigen Energie.\n\nDie Euroloopantenne liest die Telegramme aus den im Gleis verlegten Euroloop.\n\nHinweise:\n\nDie Balisenantenne und die Euroloopantenne kÃ¶nnen auch als\n\nkombinierte Antenne ausgefÃ¼hrt sein.\n\nBei TÃ¤tigkeiten unter dem Fahrzeug ist das ETCS-FzG entsprechend den Regeln fÃ¼r das Bedienen des Fahrzeuges auszuschalten, damit durch die Strahlung der Balisenantenne keine\n\nGesundheitsgefÃ¤hrdung besteht.",102,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":37,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","b10840a3cf6811d990300ff6c4d553fb039bc0f5d5e73cca375a5a559092c6f8"],["chunk_6e6b4c0937577f56ce7fbf01","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",54,"Seite 38","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n38/98\n\nIn Abschnitt 7 â€žAnzeigen am MFDâ€œ Unterabschnitt â€žGeschwindigkeits- und Ãœberwachungsbereichâ€œ ist der Absatz (14) durch den folgenden zu ersetzen:\n\nRelease Speed (14) Die Release Speed dient zur AnnÃ¤herung an die in a) und b)\n\ngenannten Signale bzw. einen Gleisabschluss:\n\na) In ETCS-Level 1 in der ETCS-Betriebsart LS ermÃ¶glicht sie\n\nbis zum\n\n- Signal, das dem ETCS-FzG mittels Balise eine neue\n\nSignalinformation Ã¼bertrÃ¤gt, oder\n\n- Gleisabschluss\n\nvorzufahren.\n\nNach dem Befahren der Balise, die ca. 250 m vor\n\n- dem Halt3 zeigenden Haupt- bzw. Sperrsignal4 oder\n\n- dem Signal Ne 1\n\nliegt, wird eine Release Speed von 25 km/h angezeigt.\n\nAbweichend wird eine Release Speed von 15 km/h maximal 350 m vor\n\n- dem Gleisabschluss,\n\n- dem Sperrsignal, an dem die Zugfahrt endet oder\n\n- dem Ende einer mit ETCS-Level 1 ausgerÃ¼steten\n\nStrecke\n\nangezeigt.\n\nÃœberlagert sich die Anzeige der Release Speed mit einer\n\nLangsamfahrstelle, wird die niedrigste Geschwindigkeit als\n\nRelease Speed angezeigt.\n\nDas MFD zeigt die Release Speed nur digital an.\n\nDie Release Speed ist auch dann einzuhalten, wenn die\n\nWeiterfahrt am Haupt- bzw. Sperrsignal4 zwischenzeitlich\n\nzugelassen ist.\n\nNach Vorbeifahrt am Haupt- bzw. Sperrsignal4 wird die Release Speed gelÃ¶scht.\n\n3 Dies gilt auch bei den Signalbegriffen Zs 1, Zs 7 und Zs 8.\n\n4 Sperrsignale am Gegengleis in HÃ¶he des Einfahrsignals, ggf. Sperrsignale, die Ziel einer Zugfahrt sind und Sperrsignale vor Gruppensignalen",228,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":38,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","cd5877a23a4b4db440a898c46fa341e53f6a01e68cd7272548ec2afcb529487a"],["chunk_efdd5285bc0c08fc4df986e7","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",55,"Seite 39","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n39/98\n\nb) In ETCS-Level 2 in den ETCS-Betriebsarten FS und OS\n\nermÃ¶glicht sie bis zum\n\n- zugehÃ¶rigen Haupt- bzw. Sperrsignal5,\n\n- Signal Ne 14,\n\n- Blockkennzeichen oder\n\n- Gleisabschluss\n\nvorzufahren, um Ungenauigkeiten der Wegmessung auszugleichen.\n\nDie angezeigte Release Speed ist u. a. abhÃ¤ngig vom vorhandenen Durchrutschweg und betrÃ¤gt maximal 15 km/h\n\nbzw. eine niedrigere Geschwindigkeit, wenn sich diese mit\n\neiner Langsamfahrstelle Ã¼berlagert.\n\nHinweis:\n\nNach Halt vor dem Signal kann ETCS die Release Speed\n\nselbsttÃ¤tig bis auf 0 km/h reduzieren.\n\nDas MFD zeigt die Release Speed gleichzeitig mit dem ZurÃ¼ckfÃ¼hren der Sollgeschwindigkeit\n\n- in der ETCS-Betriebsart FS digital und analog und\n\n- in der ETCS-Betriebsart OS nur digital, nachdem Sie\n\ndiese eingeblendet haben,\n\nan.\n\nDie Release Speed wird gelÃ¶scht, wenn die Weiterfahrt zugelassen ist.\n\nBeim Ãœberschreiten der Release Speed leitet das ETCS-FzG\n\neine Zwangsbremsung bis zum Stillstand ein.\n\nHinweis:\n\nDer Abschnitt 13 â€žRegelbetriebâ€œ enthÃ¤lt entsprechende Beispiele mit Abbildungen.\n\n5 Bei Sperrsignalen abhÃ¤ngig von der ETCS-Streckensoftware.",161,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":39,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","84ec266854927f5e142c360f89eeefea0078176c7f48e24e7b64d21656ee98da"],["chunk_547b5f91673e3c32c93ab1a7","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",56,"Seite 40","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n40/98\n\nIn Abschnitt 7 â€žAnzeigen am MFDâ€œ Unterabschnitt\n\nâ€žGeschwindigkeits- und Ãœberwachungsbereichâ€œ sind\n\nin Absatz (19) in der Tabelle 4 â€žSymbole der ETCS-\n\nMeldungenâ€œ die folgenden Zeilen zu ersetzen:\n\nSymbol ETCS-Meldung Bedeutung\n\nZwangsbetriebsbremsung oder Bremseingriff durch ETCS\n\nZwangsbremsung Zeigt das Symbol einen gelben,\n\nblinkenden Rahmen an, ist die\n\nETCS-Meldung zu bestÃ¤tigen.\n\nFunkverbindung Funkverbindung zwischen ETCS-\n\nFzG und ETCS-Zentrale vorhanden oder kurzzeitig unterbrochen\n\nFunkverbindung unterbrochen Funkverbindung zwischen ETCS-\n\nFzG und ETCS-Zentrale konnte\n\nnicht aufgebaut werden oder ist\n\nunterbrochen",83,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":40,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","afbc0758cbe176539e7d9a6f32c06696cf22f3596778139feb0a13d3b008cf67"],["chunk_97a5261b3108c7a051d893ef","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",57,"Seite 41","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n41/98\n\nIn Abschnitt 7 â€žAnzeigen am MFDâ€œ Unterabschnitt\n\nâ€žGeschwindigkeits- und Ãœberwachungsbereichâ€œ sind\n\nin Absatz (21) in der Tabelle 6 â€žSymbole der ETCS-\n\nStreckeneigenschaftenâ€œ die folgenden Zeilen zu ersetzen:\n\nSymbol Bedeutung\n\nAnkÃ¼ndigung eines Bereichs, in dem die Wirbelstrombremse nicht zugelassen ist.\n\nDie Wirbelstrombremse ist manuell zu sperren.\n\nPrÃ¼fen Sie, ob der Schaltzustand der Wirbelstrombremse (freigegeben\n\noder gesperrt) der im Fahrplan angegebenen Bremsstellung entspricht.\n\nFalls nicht, halten Sie an und sperren die Wirbelstrombremse entsprechend den Regeln fÃ¼r das Bedienen des Fahrzeuges.\n\nHinweise:\n\nDas Symbol fÃ¼r die AnkÃ¼ndigung wird nur angezeigt, wenn sich die Streckeneigenschaft fÃ¼r die Verwendung der Wirbelstrombremse innerhalb\n\neiner Strecke mit ETCS-Level 2 Ã¤ndert.\n\nDas Symbol unterhalb des Tachokreises wird ca. 10 s vor dem Bereich\n\nangezeigt, in dem die Wirbelstrombremse nicht zugelassen ist.\n\nAnkÃ¼ndigung eines Bereichs, in dem die Wirbelstrombremse nicht zugelassen ist.\n\nDie Wirbelstrombremse wird selbsttÃ¤tig fÃ¼r Betriebsbremsungen gesperrt.\n\nHinweise:\n\nDas Symbol fÃ¼r die AnkÃ¼ndigung wird nur angezeigt, wenn sich die Streckeneigenschaft fÃ¼r die Verwendung der Wirbelstrombremse innerhalb\n\neiner Strecke mit ETCS-Level 2 Ã¤ndert.\n\nDas Symbol unterhalb des Tachokreises wird ca. 10 s vor dem Bereich\n\nangezeigt, in dem die Wirbelstrombremse fÃ¼r Betriebsbremsungen nicht\n\nzugelassen ist.\n\nFahrzeug befindet sich in einem Bereich, in dem die Wirbelstrombremse\n\nfÃ¼r\n\n- Betriebsbremsungen oder\n\n- Schnellbremsungen und Betriebsbremsungen\n\nnicht zugelassen ist.\n\nAnzeige des Symbols nach dem Levelwechsel nach ETCS-Level 1 oder\n\nETCS-Level 2:",228,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":41,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","7c0d69026c679b08d70bf4f4efd68a5df4da9f85777c366cc0b4f8684557c8ae"],["chunk_2fac93bba03d61440d88ef48","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",58,"Seite 41","PrÃ¼fen Sie, ob der Schaltzustand der Wirbelstrombremse (freigegeben\n\noder gesperrt) der im Fahrplan angegebenen Bremsstellung entspricht.\n\nFalls nicht, halten Sie an und sperren die Wirbelstrombremse entsprechend den Regeln fÃ¼r das Bedienen des Fahrzeuges.",33,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":41,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","c93de86b8f7c116606864d4de53fd9553394871ce5a7bfa43ef920a6fc1dcf35"],["chunk_da05941b7ef25f85115dcff5","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",59,"Seite 42","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n42/98\n\nIn Abschnitt 8 â€žZusammenhang zwischen Bremskurven\n\nund Farbdarstellung der Geschwindigkeitsanzeigeâ€œ Unterabschnitt â€žWechsel zu einer neuen Zielgeschwindigkeitâ€œ ist\n\ndie Beschreibung von Bild 21 durch die folgende zu ersetzen:\n\nBild 21: AnstoÃŸ an Zwangsbremskurve\n\nBeim AnstoÃŸ an die Zwangsbremskurve V stellt das MFD die Diffeeingriff\n\nrenz zwischen V und V sowie die\n\nsoll ist\n\nTachonadel in Rot dar.\n\nDas ETCS-FzG leitet eine Zwangsbremsung (HL-Druck 0 bar) ein:\n\n- Auf Strecken mit ETCS-Level 1 fÃ¼hrt\n\ndas ETCS-FzG die Zwangsbremsung bis zum Stillstand fort.\n\n- Auf Strecken mit ETCS-Level 2 hebt\n\ndas ETCS-FzG die Zwangsbremsung wieder auf, sobald V den\n\nist\n\nWert fÃ¼r V unterschreitet.\n\nsoll\n\nHinweis:\n\nBeim Bremsen auf eine niedrigere Zielgeschwindigkeit wird beim Ãœberschreiten der V direkt eine Zwangsbremeingriff\n\nsung ausgegeben und keine Zwangsbetriebsbremsung.\n\nIn Abschnitt 8 â€žZusammenhang zwischen Bremskurven\n\nund Farbdarstellung der Geschwindigkeitsanzeigeâ€œ Unterabschnitt â€žÃœberwachung der Sollgeschwindigkeitâ€œ ist der\n\nAbsatz (1) durch den folgenden zu ersetzen:\n\nAnstoÃŸ an die (1) Beim AnstoÃŸ an die Zwangsbremskurve bleiben der Tachokreis\n\nZwangsbrems- und die Tachonadel rot.\n\nkurve\n\nDas ETCS-FzG leitet eine Zwangsbremsung (HL-Druck 0 bar)\n\nein:\n\n- Auf Strecken mit ETCS-Level 1 fÃ¼hrt das ETCS-FzG die\n\nZwangsbremsung bis zum Stillstand fort.\n\n- Auf Strecken mit ETCS-Level 2 hebt das ETCS-FzG die\n\nZwangsbremsung wieder auf, sobald V den Wert fÃ¼r V\n\nist soll\n\nunterschreitet.",217,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":42,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","2f7835c7a0653d648508ab421975cd6392e9c00ff3cb3f2c812f4d5b78895409"],["chunk_ca3b7b80cc6292577dda9528","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",60,"Seite 43","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n43/98\n\nDer Abschnitt 10 â€žETCS-Funktionenâ€œ ist durch den folgenden zu ersetzen:\n\n10 ETCS-Funktionen\n\n(1) Die StillstandsÃ¼berwachung ist in allen ETCS-Level in der Stillstands-\n\nETCS-Betriebsart SB wirksam. Ã¼berwachung\n\nBewegt sich das Fahrzeug um mehr als 5 m, leitet das ETCS-\n\nFzG eine Zwangsbetriebsbremsung oder Zwangsbremsung ein.\n\nDas MFD zeigt eine quittierungspflichtige ETCS-Meldung sowie\n\ndie Textmeldung â€žRoll- oder StillstandsÃ¼berwachung angesprochenâ€œ an.\n\nHeben Sie im Stillstand die Zwangsbetriebsbremsung oder\n\nZwangsbremsung durch BestÃ¤tigen der ETCS-Meldung auf.\n\nHinweis:\n\nIst das FÃ¼hrerpult deaktiviert, wird die quittierungspflichtige\n\nETCS-Meldung und die Textmeldung erst angezeigt, wenn das\n\nFÃ¼hrerpult aktiviert wurde.\n\n(2) Die Wegroll-/RÃ¼ckrollÃ¼berwachung ist in allen ETCS-Level wirk- Rollsam. Ã¼berwachung\n\nBewegt sich das Fahrzeug um mehr als 5 m entgegen der durch\n\ndie ETCS-Fahrterlaubnis vorgegebenen oder eingestellten\n\nFahrtrichtung, leitet das ETCS-FzG eine Zwangsbetriebsbremsung oder Zwangsbremsung ein. Das MFD zeigt eine quittierungspflichtige ETCS-Meldung sowie die Textmeldung â€žRolloder StillstandsÃ¼berwachung angesprochenâ€œ an.\n\nHeben Sie im Stillstand die Zwangsbetriebsbremsung oder\n\nZwangsbremsung durch BestÃ¤tigen der ETCS-Meldung auf.\n\n(3) In ETCS-Level 2 Ã¼berwacht das ETCS-FzG in den ETCS-Be- Ãœberwachung\n\ntriebsarten FS und OS die Funkverbindung zur ETCS-Zentrale. der Verbindung\n\nzur ETCS-\n\nIst die Funkverbindung fÃ¼r mehr als 40 s unterbrochen, leitet das\n\nZentrale\n\nETCS-FzG eine Zwangsbetriebsbremsung ein und zeigt am\n\nMFD die Textmeldung â€žVerbindung zur ETCS-Zentrale unterbrochenâ€œ oder â€žKommunikationsfehler RBCâ€œ an. Nachdem der Zug",216,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":43,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","d8121e6433cca9b6675f082d7c19d11c88a921b1d691648fdda8d7dfa81b5e4c"],["chunk_fe86bcb2a731cc28930ac4b4","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",61,"Seite 43","zum Stillstand gekommen ist, endet die ETCS-Fahrterlaubnis\n\nam aktuellen Standort und das ETCS-FzG hebt die Zwangsbetriebsbremsung auf.\n\nIst die Funkverbindung wieder vorhanden, bevor der Zug zum\n\nStillstand gekommen ist, wird die Zwangsbetriebsbremsung aufgehoben und die Textmeldung gelÃ¶scht. In diesem Fall wird die\n\nETCS-Fahrterlaubnis nicht beendet.",45,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":43,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","3775488ca1f0b4b0b17400af785a002edbb310f2749173809e16632ec89b684c"]]');
