INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_1935e50754e3c29aa0d95b83","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",62,"Seite 44","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n44/98\n\nIn Abschnitt 11 â€žVorbereitungsarbeitenâ€œ Unterabschnitt\n\nâ€žZugdaten eingeben bzw. Ã¤ndernâ€œ ist der Absatz (12) durch\n\nden folgenden zu ersetzen:\n\nZugdaten (12) Vor Beginn einer Zugfahrt, Rangierfahrt (abhÃ¤ngig von der\n\n(Train data) ETCS-Fahrzeugsoftware) oder wenn sich die Zugdaten Ã¤ndern,\n\ngeben Sie im Stillstand die erforderlichen Zugdaten durch Eingabe\n\n- der ETCS-Zugart,\n\n- des Einstellwertes ZL (ZuglÃ¤nge),\n\n- der vorhandenen Brh (Bremshundertstel) und\n\n- des Einstellwertes VMZ (maximal zulÃ¤ssige Geschwindigkeit des Zuges)\n\nam MFD ein.\n\nWenn die ETCS-Zugart fahrzeugabhÃ¤ngig geÃ¤ndert werden\n\nkann, ist die einzustellende ETCS-Zugart in den Regeln fÃ¼r das\n\nBedienen der Fahrzeuge bekanntgegeben.\n\nAls Einstellwert ZL ist die metergenaue GesamtzuglÃ¤nge einzugeben. Nachkommastellen sind auf den nÃ¤chsthÃ¶heren Meter\n\naufzurunden.\n\nDer Einstellwert VMZ ist nach folgenden Vorgaben zu ermitteln:\n\na) Ermittlung der kleinsten der nachfolgend aufgefÃ¼hrten Geschwindigkeiten:\n\n- grÃ¶ÃŸte zulÃ¤ssige Geschwindigkeit im Fahrplan\n\n- zulÃ¤ssige Geschwindigkeit des Triebfahrzeuges\n\n- zulÃ¤ssige Geschwindigkeit des Wagenzuges\n\nb) Ggf. Reduzierung der nach a) ermittelten Geschwindigkeit\n\ngemÃ¤ÃŸ den EinschrÃ¤nkungen in den Regeln fÃ¼r das Bedienen der Fahrzeuge.\n\nVMZ verringern Wenn sich nach Beginn der Zugfahrt die maximal zulÃ¤ssige Geschwindigkeit des Zuges verringert und diese GeschwindigkeitsbeschrÃ¤nkung mindestens bis zum nÃ¤chsten planmÃ¤ÃŸigen Halt\n\ndes Zuges gilt, dann ist beim nÃ¤chsten Halt der Einstellwert VMZ\n\ndementsprechend zu verringern.\n\nPrÃ¼fen Sie die Richtigkeit der eingegebenen Zugdaten.\n\nHinweis:\n\nZusÃ¤tzlich sind die Regeln fÃ¼r das Bedienen der Fahrzeuge zu\n\nbeachten.",224,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":44,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","d8f22ea5aadc8244a2c4b8c14666c3d94d1b58e9f4081fadc6e0c27f07be33af"],["chunk_f98825f3bed5e3b28cfa7389","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",63,"Seite 45","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n45/98\n\nBild 40: Zugdateneingabe ETCS (Teil 1)\n\nAuswahl Bedeutung\n\nTrain category ETCS-Zugart:\n\n- PASS x: Reisezug in Bremsstellung P\n\n- FP x: GÃ¼terzug in Bremsstellung P\n\n- FG x: GÃ¼terzug in Bremsstellung G\n\n- TILT x: Reisezug mit aktiver\n\nNeigetechnik\n\nLength (m) ZL (ZuglÃ¤nge)\n\nBrake percentage Brh (Bremshundertstel)\n\nMax speed (km/h) VMZ (maximal zulÃ¤ssige Geschwindigkeit des Zuges)\n\nTabelle 20: Zugdateneingabe ETCS (Teil 1)",70,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":45,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","44b67a8e40a232dc0e3268fd27b44d703054217917f7ebcde2931b39d4994834"],["chunk_e225b12abececefcfb0b8cad","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",64,"Seite 46","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n46/98\n\nBild 41: Zugdateneingabe ETCS (Teil 2)\n\nAuswahl Bedeutung\n\nAxle load category Streckenklasse\n\nAirtight DruckertÃ¼chtigt\n\nLoading gauge Fahrzeugbegrenzung / LÃ¼\n\nTabelle 21: Zugdateneingabe ETCS (Teil 2)\n\nIst bei der Eingabe der Zugdaten zusÃ¤tzlich die Eingabe der in\n\nTabelle 21 genannten Zugdaten erforderlich, dann geben Sie\n\ndiese nach den Regeln fÃ¼r das Bedienen der Fahrzeuge ein.\n\nDie Eingabe der Zugdaten ist zu bestÃ¤tigen.",69,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":46,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","3ec413947c205e135e782e713a1c2bd8cee685e92f263c1ad25792cababcec2d"],["chunk_45fee6029a21099be8fa3490","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",65,"Seite 47","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n47/98\n\nIn Abschnitt 12 â€žBeginn einer Zugfahrtâ€œ Unterabschnitt\n\nâ€žBeginn in ETCS-Level 1â€œ ist der Absatz (4) durch den folgenden zu ersetzen:\n\n(4) In der ETCS-Betriebsart SR wechselt das ETCS-FzG nach dem Wechsel in\n\nBefahren der Balise, die ETCS-Betriebsart LS\n\n- am Vorsignal bzw. alleinstehenden Signal Ne 2,\n\n- ca. 250 m vor dem Haupt- bzw. Sperrsignal6 oder Signal\n\nNe 1 oder\n\n- im Bereich kleiner 250 m bis zum Hauptsignal (abhÃ¤ngig\n\nvon der ETCS-StreckenausrÃ¼stung)\n\n- am Haupt- bzw. Sperrsignal6 oder Signal Ne 1\n\nliegt, in die ETCS-Betriebsart LS.\n\nDas Symbol mit einem gelben, blinkenden Rahmen fordert\n\nSie auf, den vollzogenen (nicht angekÃ¼ndigten) Wechsel in die\n\nETCS-Betriebsart LS zu bestÃ¤tigen.\n\nBestÃ¤tigen Sie innerhalb von 5 s den Wechsel in die ETCS-\n\nBetriebsart LS. Andernfalls leitet das ETCS-FzG eine Zwangsbetriebsbremsung ein, die Sie durch eine nachtrÃ¤gliche BestÃ¤tigung aufheben kÃ¶nnen.\n\nBild 49: Aufforderung zum BestÃ¤tigen des vollzogenen (nicht\n\nangekÃ¼ndigten) Wechsels in die ETCS-Betriebsart LS\n\nNach dem BestÃ¤tigen der ETCS-Betriebsart LS zeigt das MFD\n\nfolgendes Bild:\n\nBild 50: ETCS-Betriebsart LS wirksam\n\n6 Sperrsignale am Gegengleis in HÃ¶he des Einfahrsignals, ggf. Sperrsignale, die Ziel einer Zugfahrt sind und Sperrsignale vor Gruppensignalen",193,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":47,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","d00e7cd46bf4b0dd11eb1755d2c366dda7162652924ea1e6cf418d77fdafd92c"],["chunk_aa185f3ea443731a9fdcc1d2","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",66,"Seite 48","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n48/98\n\nIn Abschnitt 12 â€žBeginn einer Zugfahrtâ€œ ist der Unterabschnitt â€žBeginn in ETCS-Level 2â€œ durch den folgenden zu\n\nersetzen:\n\nBeginn in ETCS-Level 2\n\nAnfrage (5) Nach dem BetÃ¤tigen von â€žStartâ€œ sendet das ETCS-FzG eine\n\nStartanfrage an die ETCS-Zentrale, um eine ETCS-Fahrterlaubnis zu erhalten.\n\nAbhÃ¤ngig von der betrieblichen Situation und der ETCS-Streckensoftware gelten die AbsÃ¤tze (6) bis (14).\n\nWenn nach dem BetÃ¤tigen von â€žStartâ€œ am MFD eine Auswahl\n\nanderer Bedienfelder nicht mÃ¶glich ist, ist der ETCS-Startlauf erneut durchzufÃ¼hren.\n\nETCS-Betriebs- (6) Ist der ETCS-Zentrale der Standort des Zuges bekannt und hat\n\nart FS oder OS der Fdl der Zugfahrt zugestimmt, sendet die ETCS-Zentrale eine\n\nETCS-Fahrterlaubnis und das ETCS-FzG wechselt in die ETCS-\n\nBetriebsart FS oder OS.\n\nBeim Wechsel in die ETCS-Betriebsart OS fordert das ETCS-\n\nFzG eine nachtrÃ¤gliche BestÃ¤tigung des nicht angekÃ¼ndigten\n\nWechsels in die ETCS-Betriebsart OS (siehe Abschnitt 13 Absatz (9)).\n\nBild 51: Beispiel ETCS-Betriebsart FS wirksam",153,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":48,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","8c74b802d41739a12c6c137e615451d73dbf3b81938e79c47086ad6fd61c9988"],["chunk_dab0eec2f00acb172ab914fe","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",67,"Seite 49","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n49/98\n\n(7) Ist der ETCS-Zentrale der Standort des Zuges bekannt und hat ETCS-Betriebsder Fdl der Zugfahrt ab der ETCS-Blockstelle noch nicht zuge- art FS oder OS\n\nstimmt, wechselt das ETCS-FzG in die ETCS-Betriebsart FS und\n\nTextmeldung\n\noder OS und zeigt die Textmeldung â€žStartanfrage von ETCS-\n\nâ€žStartanfrage\n\nZentrale empfangenâ€œ an.\n\nvon ETCS-\n\nHinweis: Zentrale\n\nMit der Textmeldung zeigt die ETCS-Zentrale an, dass diese auf empfangenâ€œ\n\ndie Freigabe des Fahrwegs durch das Stellwerk wartet.\n\nIn AbhÃ¤ngigkeit der ETCS-StreckenausrÃ¼stung gilt Folgendes:\n\na) Die ETCS-Zentrale sendet eine ETCS-Fahrterlaubnis\n\n(V > 0 km/h) bis zur ETCS-Blockstelle.\n\nsoll\n\nb) Die ETCS-Zentrale sendet keine ETCS-Fahrterlaubnis\n\n(V = 0 km/h).\n\nsoll\n\nBeim Wechsel in die ETCS-Betriebsart OS fordert das ETCS-\n\nFzG eine nachtrÃ¤gliche BestÃ¤tigung des nicht angekÃ¼ndigten\n\nWechsels in die ETCS-Betriebsart OS (siehe Abschnitt 13 Absatz (9)).\n\nSobald der Fdl der Zugfahrt zugestimmt hat, sendet die ETCS-\n\nZentrale eine ETCS-Fahrterlaubnis Ã¼ber die ETCS-Blockstelle\n\nhinaus.\n\n(8) Ist der ETCS-Zentrale der Standort des Zuges unbekannt und Textmeldung\n\nhat der Fdl der Zugfahrt noch nicht zugestimmt, sendet die â€žStartanfrage\n\nETCS-Zentrale die Textmeldung â€žStartanfrage von ETCS-Zent- von ETCS-\n\nZentrale\n\nrale empfangenâ€œ.\n\nempfangenâ€œ\n\nHinweis:\n\nMit der Textmeldung zeigt die ETCS-Zentrale an, dass diese auf\n\ndie Freigabe des Fahrwegs durch das Stellwerk wartet.\n\nWenn der Fdl der Zugfahrt zugestimmt hat, kann das ETCS-FzG\n\neine Textmeldung gemÃ¤ÃŸ Absatz (9) oder (10) anzeigen.\n\n(9) Mit der Textmeldung â€žSie dÃ¼rfen ohne Bedienen Override EOA Textmeldung\n\nvorbeifahren an ETCS-Bk ... [Signalbezeichnung]â€œ zeigt die â€žSie dÃ¼rfen",244,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":49,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","38c368c17f336c326e68ace6db62c93cde2f411ca314c5b6e3faf9540379649d"],["chunk_85cac0d170196b63013e9c33","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",68,"Seite 49","ETCS-Zentrale an, dass sie keine ETCS-Fahrterlaubnis senden ohne Bedienen\n\nOverride EOA\n\nkann, da der ETCS-Zentrale der Standort des Zuges unbekannt\n\nvorbeifahren an\n\nist.\n\nETCS-Bk ...â€œ\n\nGleichzeitig sendet die ETCS-Zentrale eine AnkÃ¼ndigung fÃ¼r\n\nden Wechsel in die ETCS-Betriebsart SR (weiter gemÃ¤ÃŸ Absatz\n\n(14)).",42,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":49,\"source_id