INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_c67fa1945f2c31758b069c90","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",82,"Seite 59","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n59/98\n\nBild 59: Beispiel mit aktivem â€žOverrideâ€œ und Wechsel in die\n\nETCS-Betriebsart SR (ohne eingeblendete ÃœberwachungsgrÃ¶ÃŸen)\n\nâ€žOverrideâ€œ\n\n(22) Das Symbol erlischt und â€žOverrideâ€œ ist nicht mehr aktiv,\n\nerlischt\n\na) nachdem Sie an einer aus Absatz (21) b) und c) genannten\n\nStelle vorbeigefahren sind oder\n\nb) nach\n\n- ZurÃ¼cklegen einer Entfernung von 400 m oder\n\n- Ablauf einer Zeit von 255 s.\n\nFÃ¼r ETCS-Level 0 trifft nur b) zu.\n\nErlischt das Symbol , bevor Sie an dem im Befehl genannten\n\nSignal oder Blockkennzeichen vorbeigefahren sind, ist kein zusÃ¤tzlicher Befehl zum erneuten Bedienen von â€žOverrideâ€œ erforderlich.\n\nHinweis:\n\nMit jedem Bedienen von â€žOverrideâ€œ beginnt die Ãœberwachung\n\nder Entfernung und Zeit erneut.",115,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":59,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","4a2a8e25dd9d383317167894b8474882cf5455afdb691a0171d5d5339cac40b1"],["chunk_3e8349b560577c51aa5c5aa2","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",83,"Seite 60","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n60/98\n\nIn Abschnitt 13 â€žRegelbetriebâ€œ ist der Unterabschnitt\n\nâ€žFahrt in der ETCS-Betriebsart SRâ€œ durch den folgenden zu\n\nersetzen:\n\nFahrt in der ETCS-Betriebsart SR\n\nÃœberwachungs- (23) Nachdem das ETCS-FzG in die ETCS-Betriebsart SR gewechgrÃ¶ÃŸen in der selt ist, mÃ¼ssen Sie die ÃœberwachungsgrÃ¶ÃŸen einblenden (siehe\n\nETCS-Betriebs- Abschnitt 7 Tabelle 8).\n\nart SR einblenden Zum Einblenden der ÃœberwachungsgrÃ¶ÃŸen ist\n\n- beim Softkey-Display der Softkey zu betÃ¤tigen oder\n\n- beim Touchscreen-Display in den Bereich der Geschwindigkeitsanzeige des MFD zu tippen.\n\nDas ETCS-FzG Ã¼berwacht die zulÃ¤ssige Geschwindigkeit\n\n- von 20 km/h auf Strecken mit ETCS-Level 1 und\n\n- von 40 km/h auf Strecken mit ETCS-Level 2\n\noder ggf. eine niedrigere Geschwindigkeit.\n\nHinweis:\n\nEine niedrigere Geschwindigkeit wird z. B. angezeigt, wenn die\n\nentsprechenden Balisen verlegt sind.",127,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":60,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","876db960abe503f3b38bd1bae0a87992a2deb86d9d1b5c48eb3af83ccfae73d0"],["chunk_9a349fd7643d374237dbc02a","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",84,"Seite 61","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n61/98\n\nBild 60: Beispiel einer Fahrt in ETCS-Level 2 in der ETCS-\n\nBetriebsart SR (mit eingeblendeten ÃœberwachungsgrÃ¶ÃŸen)\n\nBild 61: Beispiel einer Fahrt in ETCS-Level 2 in der ETCS-\n\nBetriebsart SR (mit eingeblendeten ÃœberwachungsgrÃ¶ÃŸen)\n\nund einer angekÃ¼ndigten Langsamfahrstelle mit 10 km/h",47,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":61,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","0bf7e11ce20379e60960e2c10381c0ccd6f5b3c8047a0bcf0d25b7d1b46e057e"],["chunk_bdba45cec50ba16492bb9e00","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",85,"Seite 62","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n62/98\n\nIn Abschnitt 13 â€žRegelbetriebâ€œ ist der Unterabschnitt â€žHalt\n\nin der ETCS-Betriebsart SRâ€œ durch den folgenden zu ersetzen:\n\nHalt in der ETCS-Betriebsart SR\n\nAnzeige Sollge- (24) Die Sollgeschwindigkeit zeigt auf Strecken\n\nschwindigkeit\n\n- mit ETCS-Level 1 weiterhin 20 km/h und\n\n- mit ETCS-Level 2 weiterhin 40 km/h\n\nan. Ggf. kann eine niedrigere Geschwindigkeit angezeigt werden, z. B. bei einer Langsamfahrstelle.\n\nIn ETCS-Level 2 kann ca. 100 m vor einem Signal Ne 14 die\n\nSollgeschwindigkeit auf 20 km/h reduziert werden, wenn der\n\nDurchrutschweg zu gering ist.\n\nIn Abschnitt 13 â€žRegelbetriebâ€œ ist der neue Unterabschnitt\n\nâ€žWechsel von der ETCS-Betriebsart SR in die ETCS-\n\nBetriebsart LSâ€œ (nach â€žHalt in der ETCS-Betriebsart SRâ€œ)\n\neinzufÃ¼gen:\n\nWechsel von der ETCS-Betriebsart SR in die ETCS-\n\nBetriebsart LS\n\nWechsel in die (25) Auf Strecken mit ETCS-Level 1 wechselt das ETCS-FzG nach\n\nETCS-Betriebs- dem Befahren der Balise, die\n\nart LS\n\n- am Vorsignal bzw. alleinstehenden Signal Ne 2,\n\n- ca. 250 m vor dem Haupt- bzw. Sperrsignal11 oder Signal\n\nNe 1 oder\n\n- im Bereich kleiner 250 m bis zum Hauptsignal (abhÃ¤ngig\n\nvon der ETCS-StreckenausrÃ¼stung)\n\n- am Haupt- bzw. Sperrsignal11 oder Signal Ne 1\n\nliegt, in die ETCS-Betriebsart LS.\n\nBestÃ¤tigen Sie innerhalb von 5 s den Wechsel in die ETCS-\n\nBetriebsart LS. Andernfalls leitet das ETCS-FzG eine Zwangsbetriebsbremsung ein, die Sie durch eine nachtrÃ¤gliche BestÃ¤tigung aufheben kÃ¶nnen.\n\n11 Sperrsignale am Gegengleis in HÃ¶he des Einfahrsignals, ggf. Sperrsignale, die Ziel einer Zugfahrt sind und Sperrsignale vor Gruppensignalen",244,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":62,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","6ac11a94f19ca59bc516a7d1f680c0e30fc75f926af87a1d1f430448ab97f63d"],["chunk_4dfa70147293dada96be2d52","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",86,"Seite 63","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n63/98\n\nIn Abschnitt 13 â€žRegelbetriebâ€œ ist der Unterabschnitt\n\nâ€žETCS-Betriebsart SHâ€œ durch den folgenden zu ersetzen:\n\nETCS-Betriebsart SH\n\n(26) BetÃ¤tigen Sie im Grundbild â€žHauptmenÃ¼â€œ (Main) und anschlie- ETCS-BetriebsÃŸend im MenÃ¼ â€žHauptmenÃ¼â€œ den Unterpunkt â€žSHâ€œ oder â€žRangie- art SH wÃ¤hlen\n\nren (SH)â€œ (Shunting), um in die ETCS-Betriebsart SH zu wechseln.\n\n(27) In ETCS-Level NTC PZB/LZB wechselt das ETCS-FzG sofort in ETCS-Level NTC\n\ndie ETCS-Betriebsart SH, wenn diese abhÃ¤ngig von der ETCS- PZB/LZB\n\nFahrzeugsoftware verfÃ¼gbar ist:\n\na) Ist diese verfÃ¼gbar, darf zum Rangieren in diese gewechselt werden, wenn\n\n- mit Notfalltechnik im Fall dringlicher Anforderung,\n\n- im Rahmen von Arbeiten auf Grundlage einer\n\nBetriebs- und Bauanweisung (Betra) oder\n\n- voraussichtlich lÃ¤nger als 30 Minuten oder\n\n- mit Funkfernsteuerung\n\nrangiert wird.\n\nHinweis:\n\nMit dem Wechsel in die ETCS-Betriebsart SH wird das\n\nPZB-FzG ausgeschaltet.\n\nb) Ist diese nicht verfÃ¼gbar, geben Sie zum Rangieren die fÃ¼r\n\ndie anschlieÃŸende Zugfahrt erforderlichen Zugdaten fÃ¼r\n\nETCS ein. SchlieÃŸt sich keine Zugfahrt an oder sind Ihnen\n\ndie fÃ¼r eine anschlieÃŸende Zugfahrt erforderlichen Zugdaten fÃ¼r ETCS nicht bekannt, geben Sie fÃ¼r ETCS die Zugdaten des Fahrzeuges sowie als Einstellwert VMZ â€ž40â€œ ein.\n\nWÃ¤hlen Sie die ETCS-Zugart aus, die zu den vorhandenen\n\nBrh des Fahrzeuges sowie zu dessen Bremsstellung passt.\n\nHinweise:\n\nFÃ¼r Rangierfahrten in ETCS-Level NTC PZB/LZB sind keine\n\nZugdaten erforderlich.\n\nIst nach dem Rangieren eine Zugfahrt durchzufÃ¼hren, fÃ¼r die Sie\n\ndie erforderlichen Zugdaten noch nicht eingegeben haben bzw.\n\ndie nicht im ETCS-Level NTC PZB/LZB beginnt, ist nach dem\n\nBeenden des Rangierens ein erneuter ETCS-Startlauf durchzufÃ¼hren.",251,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":63,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","f5defe05d68867a7f2b80e75360f42e1ecfd8dd2ac34727e3a6d6391379c6a9e"],["chunk_4408d3df8b6f7a6420274158","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",87,"Seite 63","(28) In ETCS-Level 0 und ETCS-Level 1 wechselt das ETCS-FzG ETCS-Level 0 /\n\nsofort in die ETCS-Betriebsart SH. ETCS-Level 1",20,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6bc70b0ec7631ab8215a35f/483-0701-Ausnahme-104-Akt-02-data.pdf\",\"normalized_sha256\":\"c1c4f4ca68870d8fa3e9c435e0febb13dabc88f7d4c8c7471edfd17d24415ea8\",\"page\":63,\"source_id\":\"src_d87848f5dd80f7d88d61\",\"source_sha256\":\"d19a9591dc7609ff165c99179de1ff66c7a73ac7549d36c7c67fc8a1fa69d230\",\"source_version_id\":\"sv_48daa4bf358e4fd6ee61af75\"}","c8a0ceb8fb11af7a21cf6acd4434290100b7cdfa68cd07154c9753633e4b8513"],["chunk_996c4a4d30346e7f8a94f20d","wiki/sources/483-0701-ausnahme-104-akt-02-data.md",88,"Seite 64","Ausnahme 104 Aktualisierung 02\n\nzur Richtlinie 483.0701\n\n64/98\n\nETCS-Level 2 (29) In ETCS-Level 2 stellen Sie eine Anfrage an die ETCS-Zentrale\n\nzum Wechsel in die ETCS-Betriebsart SH. Die ETCS-Zentrale\n\nstimmt in der Regel sofort zu und das ETCS-FzG wechselt in die\n\nETCS-Betriebsart SH.\n\nAbhÃ¤ngig von der betrieblichen Situation und der ETCS-Streckensoftware gibt es folgende Ausnahmen:\n\na) Die Textmeldung â€žSH abgelehntâ€œ oder â€žAnfrage SH abgelehntâ€œ wird angezeigt, wenn die ETCS-Zentrale den Wechsel in die ETCS-Betriebsart SH zunÃ¤chst ablehnt.\n\nAnschlieÃŸend sendet die ETCS-Zentrale eine der folgenden Textmeldungen:\n\n- â€žHaltstellung des folgenden Signals erforderlichâ€œ\n\nDie Textmeldung wird angezeigt, wenn an einer\n\nETCS-Blockstelle die Zustimmung zur Weiterfahrt\n\nals Zugfahrt vorliegt.\n\nDer Fdl ist zu verstÃ¤ndigen.\n\nDie Textmeldung ist zu bestÃ¤tigen und die Anfrage\n\nzum Wechsel in die ETCS-Betriebsart SH ist erneut\n\ndurchzufÃ¼hren, nachdem der Fdl die Zulassung der\n\nZugfahrt zurÃ¼ckgenommen hat.\n\n- â€žZum Rangieren ist die Zustimmung des WeichenwÃ¤rters erforderlichâ€œ\n\nDie Textmeldung wird angezeigt, wenn der Standort\n\ndes Fahrzeuges unbekannt ist.\n\nDer Fdl ist zu verstÃ¤ndigen.\n\nDie Textmeldung darf erst bestÃ¤tigt werden, wenn\n\nder Ww der Rangierfahrt zugestimmt hat. Mit dem\n\nBestÃ¤tigen der Textmeldung wechselt das ETCS-\n\nFzG in die ETCS-Betriebsart SH.\n\nHinweis:\n\nHat der Ww der Rangierfahrt bereits zugestimmt, ist\n\naufgrund der Textmeldung keine erneute Zustimmung des Ww erforderlich.\n\nb) Die Textmeldung â€žAnfrage SH fehlgeschlagenâ€œ wird angezeigt, wenn die Anfrage zum Wechsel in die ETCS-Betriebsart SH von der ETCS-Zentrale unbeantwortet bleibt,\n\nz. B. wegen Funkausfall.\n\nWechseln Sie zum Rangieren in die ETCS-Betriebsart IS\n\noder NP.",242,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13503732/bc98bc29c6b