INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_2eafa07608c4b8084b550698","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",9,"Seite 6","abgeschalteter oder gestÃ¶rter Oberleitung verhindern kann, dass der TriebfahrzeugfÃ¼hrer mit\n\ngehobenem Stromabnehmer in solche Bereiche einfÃ¤hrt und damit ggf. Leib und Leben\n\ngefÃ¤hrden werden. Wenn der TriebfahrzeugfÃ¼hrer den Wechsel der Traktionsart wiederholt\n\ndurchfÃ¼hren will, muss eine neue VerstÃ¤ndigung getroffen werden. Damit wird sichergestellt,\n\ndass es in der VerstÃ¤ndigung und Zustimmung zwischen TriebfahrzeugfÃ¼hrer und WeichenwÃ¤rter\n\nnicht zu MissverstÃ¤ndnissen und Verwechslungen kommt.\n\nMit freundlichen GrÃ¼ÃŸen\n\nDB InfraGO AG, GeschÃ¤ftsbereich Fahrweg\n\nChristian Ehrhardt Julian Huth\n\nLeiter Grundlagen und Verfahren Experte Fahrdienstvorschrift\n\nBahnbetrieb\n\nSeite 6 von 6",83,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":6,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","b983a08288437951e46e121f12c9f92ddb1523751267e7a8e3f485b96a9f7b0e"],["chunk_461112adad794586e37377e7","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",10,"Seite 7","Bahnbetrieb Fahrdienstvorschrift\n\nGrundsÃ¤tze; Begriffe 408.0055\n\nSeite 1\n\n1 Zweck, Schutzziel und Zielgruppe\n\nZweck, Schutzziel:\n\nDiese Richtlinie gewÃ¤hrleistet die Verwendung einheitlicher Begriffe im Bahnbetrieb und somit alle Anwender das gleiche VerstÃ¤ndnis dafÃ¼r haben. Dadurch wird\n\ndie Handlungssicherheit bei der Dokumentation und Kommunikation sichergestellt,\n\ndie zur GewÃ¤hrleistung der Betriebssicherheit beitrÃ¤gt.\n\nZielgruppe:\n\n- Mitarbeiter, die Aufgaben im Bahnbetrieb wahrnehmen\n\n- Mitarbeiter, die Planungs-, Leitungs- oder Ãœberwachungsaufgaben wahrnehmen\n\n- Mitarbeiter, die Ausbildung im Bahnbetrieb durchfÃ¼hren\n\n2 Regelung\n\nAblaufen, AbdrÃ¼cken\n\nAblaufen ist das Bewegen von Fahrzeugen durch Schwerkraft im Allgemeinen von\n\neinem Ablaufberg herab, Ã¼ber den die Fahrzeuge abgedrÃ¼ckt werden.\n\nAbstellen\n\nZÃ¼ge und Triebfahrzeuge sind abgestellt, wenn sie nicht mit einem Tf besetzt sind\n\noder nicht gesteuert werden. Wagen sind abgestellt, sofern sie nicht in ZÃ¼ge eingestellt sind oder nicht rangiert werden.\n\nAbstoÃŸen\n\nAbstoÃŸen ist das Bewegen geschobener, nicht mit einem arbeitenden Triebfahrzeug gekuppelter Fahrzeuge durch Beschleunigen, so dass die Fahrzeuge allein\n\nweiterfahren, nachdem das Triebfahrzeug angehalten hat.\n\nAbzweigstellen\n\nAbzweigstellen sind Blockstellen der freien Strecke, wo ZÃ¼ge von einer Strecke auf\n\neine andere Strecke Ã¼bergehen kÃ¶nnen. Eine Abzweigstelle wird durch ihre\n\nBlocksignale bzw. Signale Ne 14 begrenzt.\n\nAnschlussbahnhÃ¶fe\n\nAnschlussbahnhÃ¶fe haben besondere Aufgaben bei der Meldung der ZÃ¼ge.\n\nAnschlussstellen, Ausweichanschlussstellen\n\nAnschlussstellen sind Bahnanlagen der freien Strecke, wo ZÃ¼ge ein angeschlossenes Gleis als Rangierfahrt befahren kÃ¶nnen. Es sind zu unterscheiden:",213,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":7,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","4ea8536dd3b089a3730a2bf6ca5929ec70140ee32e449e7198a1bee8b07618f2"],["chunk_45057ac3b995dc68e05245dc","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",11,"Seite 7","Fachautor: I.IBB 31; Jens Rasch; Tel.: [E-Mail-Adresse entfernt] GÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",13,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":7,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","e8aa42e80dc47aea5f0baca9e7fa4f7fab8d8db0c8540bf99523fcfcca0b5cf3"],["chunk_9ddcafe525c702715ec6fde5","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",12,"Seite 8","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 2\n\na) Anschlussstellen, bei denen die Blockstrecke nicht fÃ¼r einen anderen Zug\n\nfreigegeben wird,\n\nb) Anschlussstellen, bei denen die Blockstrecke fÃ¼r einen anderen Zug freigegeben wird (Ausweichanschlussstellen).\n\nAnzeigegefÃ¼hrt\n\nEin Zug ist anzeigegefÃ¼hrt, wenn eine Zugbeeinflussung (LZB, ETCS) wirkt, die den\n\nZug selbsttÃ¤tig zum Halten bringen kann und auÃŸerdem fÃ¼hrt, d. h. FÃ¼hrungsgrÃ¶ÃŸen\n\nim FÃ¼hrerraum anzeigt, die fÃ¼r den Fahrtverlauf zulÃ¤ssigen Geschwindigkeiten kontinuierlich Ã¼berwacht und ggf. die Geschwindigkeit selbsttÃ¤tig regelt.\n\nAnzeigegefÃ¼hrte ZÃ¼ge kÃ¶nnen LZB-gefÃ¼hrt oder ETCS-gefÃ¼hrt sein.\n\nArbeitendes Triebfahrzeug\n\nEin Triebfahrzeug ist arbeitend, wenn es Antriebskraft erzeugt.\n\naS-Zug\n\naS-ZÃ¼ge sind ZÃ¼ge mit hÃ¤ufig vorkommenden auÃŸergewÃ¶hnlichen Sendungen, die\n\nim Fahrplan fÃ¼r Zugmeldestellen und Streckenfahrplan durch den Zusatz â€žaSâ€œ hinter\n\nder Zugnummer gekennzeichnet sind.\n\nAufdrÃ¼cken\n\nAufdrÃ¼cken ist das Bewegen von Fahrzeugen zum Entkuppeln oder von kuppelreif\n\nstehenden Fahrzeugen zum Kuppeln.\n\nAufgehobene SignalabhÃ¤ngigkeit\n\nSignalabhÃ¤ngigkeit ist in folgenden FÃ¤llen aufgehoben:\n\n- Ein Hauptsignal kann auf Fahrt gestellt werden und eine Fachkraft hat im Arbeits- und StÃ¶rungsbuch die AbhÃ¤ngigkeit fÃ¼r aufgehoben erklÃ¤rt.\n\n- Ein Hauptsignal kann auf Fahrt gestellt werden und die Zungen- oder HerzstÃ¼ckverschlÃ¼sse von Weichen wirken nicht ordnungsgemÃ¤ÃŸ.\n\nBei einer virtuellen Blockstelle entspricht deren Fahrtmelder der Fahrtstellung des\n\nHauptsignals.\n\nBahnanlagen\n\nEs gibt Bahnanlagen der BahnhÃ¶fe, der freien Strecke und sonstige Bahnanlagen.\n\nBahnbetrieb\n\nBahnbetrieb ist das Bewegen von Fahrzeugen.\n\nZum Bahnbetrieb gehÃ¶ren das Fahren von ZÃ¼gen und das Rangieren.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",223,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":8,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","32a461107222e1e024a9f75d4577385d538db3f465001e749fb754d7bd3efda8"],["chunk_44308d9c0db42e920abc6a21","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",13,"Seite 9","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 3\n\nBahnhÃ¶fe, Bahnhofsteile\n\nBahnhÃ¶fe sind Bahnanlagen mit mindestens einer Weiche, wo ZÃ¼ge beginnen, enden, halten, kreuzen, Ã¼berholen oder wenden dÃ¼rfen. BahnhÃ¶fe kÃ¶nnen in Bahnhofsteile unterteilt sein. Bahnhofsteile kÃ¶nnen durch Zwischensignale bzw. Signale\n\nNe 14 gegeneinander abgegrenzt sein.\n\nBalise, Balisengruppe\n\nEine Balise ist ein im Gleis angeordnetes DatenÃ¼bertragungselement.\n\nBei ETCS Ã¼bertragen Balisen Informationen zur Fahrzeugortung. Um die Fahrtrichtung eindeutig herleiten zu kÃ¶nnen, kÃ¶nnen Balisen zu einer Balisengruppe zusammengefasst sein. Bei ETCS-Level 1 Ã¼bertragen schaltbare Balisen zusÃ¤tzlich zur\n\nOrtung auch ETCS-Fahrterlaubnisse. An Signalen Ne 14 sind Balisen mit der Information â€žHalt in ETCS-Betriebsart SRâ€œ verlegt.\n\nBei Neigetechnik Ã¼bertragen Balisen Informationen fÃ¼r die GeschwindigkeitsÃ¼berwachung fÃ¼r Neigetechnik.\n\nBedarfshalt\n\nEin Bedarfshalt ist ein Fahrplanhalt, bei dem ein Zug auf der Betriebsstelle halten\n\nmuss, wenn:\n\n- der Tf ein Haltsignal oder ein blinkendes Signal Ne 5 erhÃ¤lt,\n\n- der Tf Reisende bemerkt, die ein- oder aussteigen wollen,\n\n- die Fahrgasthaltewunscheinrichtung dem Tf einen Haltewunsch anzeigt oder\n\n- der Tf nicht verstÃ¤ndigt wurde, dass der Halt ausfallen darf.\n\nBeidrÃ¼cken\n\nBeidrÃ¼cken ist das Bewegen getrennt stehender Fahrzeuge zum Kuppeln.\n\nBetriebliche Abfahrtszeit\n\nDie betriebliche Abfahrtszeit ist fÃ¼r die Abfahrt des Zuges auf einer Betriebsstelle\n\nmaÃŸgeblich.\n\nIn den FahrplÃ¤nen dieser Betriebsstellen kÃ¶nnen daneben auch verkehrliche Abfahrtszeiten verÃ¶ffentlich sein.\n\nBetriebshalt\n\nEin Betriebshalt ist ein Fahrplanhalt, bei dem ein Zug auf der Betriebsstelle halten\n\nmuss, wenn der Tf ein Haltsignal erhÃ¤lt.\n\nBetriebsstellen\n\nBetriebsstellen sind:",226,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":9,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","707406ca924bc400872f6d8485a2f612b14c91442c5972dc97c686f6c4e10384"],["chunk_b6aa85bc172145857aa8d93b","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",14,"Seite 9","a) BahnhÃ¶fe, Blockstellen, Abzweigstellen, Anschlussstellen, Haltepunkte,\n\nHaltestellen, Deckungsstellen, Ãœberleitstellen oder\n\nb) Stellen in den BahnhÃ¶fen oder auf der freien Strecke, die der unmittelbaren\n\nRegelung und Sicherung der Zugfahrten und des Rangierens dienen.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",37,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":9,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","c0625ab620bddbb217ea1653b6ad5890435cd1822d0ce8a926fe75e7e774e17b"],["chunk_14640eed8deaa1373780b679","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",15,"Seite 10","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 4\n\nBezeichnung des Arbeitsplatzes\n\nDie Bezeichnung setzt sich zusammen aus der Funktion des Mitarbeiters und dem\n\nNamen der Betriebsstelle, der sein Arbeitsplatz zugeordnet ist. Auf Betriebsstellen\n\nmit mehreren BedienplÃ¤tzen, kann diese durch eine Nummerierung ergÃ¤nzt sein.\n\nBlockstellen\n\nBlockstellen sind Bahnanlagen, die eine Blockstrecke begrenzen. Eine Blockstelle\n\nkann zugleich als Bahnhof, Abzweigstelle, Ãœberleitstelle, Anschlussstelle, Haltepunkt, Haltestelle oder Deckungsstelle eingerichtet sein.\n\nEs gibt Blockstellen fÃ¼r signalgefÃ¼hrte ZÃ¼ge, fÃ¼r anzeigegefÃ¼hrte ZÃ¼ge und fÃ¼r ZÃ¼ge\n\nin ETCS-Betriebsart SR.\n\nBlockstellen fÃ¼r signalgefÃ¼hrte ZÃ¼ge sind an Hauptsignalen eingerichtet.\n\nBlockstellen fÃ¼r anzeigegefÃ¼hrte ZÃ¼ge sind eingerichtet an Hauptsignalen oder als\n\nvirtuelle Blockstellen.\n\nBlockstellen fÃ¼r ZÃ¼ge in ETCS-Betriebsart SR sind an Signalen Ne 14 eingerichtet.\n\nBlockstrecken\n\nBlockstrecken sind Gleisabschnitte, in die ein Zug nur einfahren darf, wenn sie frei\n\nvon Fahrzeugen sind. Es gibt Blockstrecken fÃ¼r signalgefÃ¼hrte und fÃ¼r anzeigegefÃ¼hrte ZÃ¼ge.\n\nDeckungsstellen\n\nDeckungsstellen sind Bahnanlagen der freien Strecke, die den Bahnbetrieb insbesondere an beweglichen BrÃ¼cken, Kreuzungen von Bahnen, Gleisverschlingungen\n\noder Baustellen sichern.\n\nDurchgehende Hauptgleise\n\nDurchgehende Hauptgleise sind die Hauptgleise der freien Strecke und ihre Fortsetzung in den BahnhÃ¶fen.\n\nDynamischer Schriftanzeiger\n\nEin Dynamischer Schriftanzeiger ist ein Reisendeninformationssystem, dass an\n\nBahnsteigen optisch/akustisch Zuginformationen ausgibt. Daneben kann der DSA\n\nFreitexte anzeigen.\n\nEin DSA informiert Ã¼ber Zugplandaten und z. B. Ã¼ber folgende GeschÃ¤ftsvorfÃ¤lle\n\nzur Reisendeninformation:",206,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":10,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","8e44b6fa0966befd4c48e854745b27ae4b719a0978be6201db002a70ef9f5d9b"],["chunk_d5f0ba6ac3eb136f6209b5a4","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",16,"Seite 10","VerspÃ¤tung, Gleiswechsel, Ausfall eines Zuges, Ausfall eines Zuges auf Teilstrecken, Umleitung eines Zuges, Ersatzzug, Zusatzzug, Sonderzug.\n\nEinfahrweiche\n\nDie Einfahrweiche ist die erste Weiche eines Bahnhofs, die bei Einfahrt von der\n\nfreien Strecke her befahren wird.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",40,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":10,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","cb2a821b6f521fd55fa3c9a283a2468d54c7404ba56732d2198bfa92e56c8084"],["chunk_17fbcdbfa5e1d3aedfd2c7ff","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",17,"Seite 11","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 5\n\nEOA (End Of Authority)\n\nFÃ¼r ETCS-gefÃ¼hrte ZÃ¼ge ist ein ETCS-Halt (EOA) das Ende der ETCS-Fahrterlaubnis. Der EOA befindet sich am Signal Ne 14 oder an einer virtuellen Blockstelle. Ein\n\nEOA kann sich auch an der Spitze eines Zuges befinden, wenn eine Sollgeschwindigkeit von 0 km/h angezeigt wird oder am Sperrsignal.\n\nFÃ¼r LZB-gefÃ¼hrte ZÃ¼ge ist ein LZB-Halt (EOA) an Hauptsignalen oder virtuellen\n\nBlockstellen eingerichtet. Ein EOA kann sich auch an der Spitze eines Zuges befinden, wenn eine Sollgeschwindigkeit von 0 km/h angezeigt wird.\n\nFÃ¼r signalgefÃ¼hrte ZÃ¼ge gelten Halt zeigende Signale (EOA) als Ende der Erlaubnis\n\nzur Fahrt.\n\nETCS-Fahrterlaubnis\n\nDie ETCS-Fahrterlaubnis ist die Erlaubnis fÃ¼r einen ETCS-gefÃ¼hrten Zug bis zu einem ETCS-Halt zu fahren.\n\nETCS-Halt\n\nSiehe Begriff â€žEOA (End Of Authority)â€œ.\n\nETCS-Zentrale\n\nZu einer ETCS-Zentrale gehÃ¶ren:\n\n- die ETCS-Bedieneinrichtung,\n\n- ein sicheres Rechnersystem und\n\n- die Schnittstellen zu den Stellwerken, ETCS-Nachbarzentralen und zum GSM-R.\n\nDie ETCS-Zentrale wird auch als â€žRBCâ€œ bezeichnet.\n\nFahrdienstleiter\n\nFdl regeln die DurchfÃ¼hrung der Zugfahrten. Fdl dÃ¼rfen auch die TÃ¤tigkeiten von\n\nWw verrichten.\n\nFdl und Ww sind in den Richtlinien zusammenfassend in Kurzform auch als â€žBedienerâ€œ angesprochen.\n\nEin Bahnhof kann in mehrere Fahrdienstleiterbezirke aufgeteilt sein.\n\nSelbsttÃ¤tige Blockstellen des automatischen Streckenblocks sind auf zweigleisigen\n\nStrecken dem Fdl der vorgelegenen Zugmeldestelle, auf eingleisigen Strecken einem festgelegten Fdl zugeteilt. SelbsttÃ¤tige Blockstellen der Ã¼brigen Blockbauformen, Blockstellen fÃ¼r anzeigegefÃ¼hrte ZÃ¼ge oder Ã¶rtlich nicht besetzte BahnhÃ¶fe\n\noder Abzweigstellen gelten als mit dem Fdl besetzt, der die Signalanlagen dieser",238,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":11,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","cdc251f0fc016266c15ece44dafb447ebe204fb2d861bb98403ec65452ebd967"],["chunk_c0d7da4f383e04215a49ba29","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",18,"Seite 11","Stellen bedient.\n\nFahrplanhalt\n\nEs gibt folgende Fahrplanhalte: Regelhalt, Bedarfshalt, Betriebshalt und Halt zum\n\nSichern eines BahnÃ¼bergangs.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",21,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":11,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","0a84b999b148e64eb7b2e75ae7f37dac0e1b77e55fd9592a61ee734c5a448805"],["chunk_fe28075b3529825ec314505b","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",19,"Seite 12","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 6\n\nFahrtstellung eines Hauptsignals, Hauptsignal auf Fahrt stellen\n\nFahrtstellung eines Hauptsignals bzw. Formulierungen wie â€žein Hauptsignal auf\n\nFahrt stellenâ€œ umfassen jede Signalstellung eines Hauptsignals, die es dem Tf eines\n\nZuges erlaubt, an dem Signal vorbeizufahren, z. B. Signal Hp 2, Ks 1, Hl 3a, Sv 4.\n\nAn einer virtuellen Blockstelle entspricht der Fahrtstellung des Hauptsignals der entsprechende Fahrtmelder.\n\nFahrzeuge\n\nFahrzeuge werden unterschieden nach Regelfahrzeugen und Nebenfahrzeugen.\n\nFahrzeuge mit unzureichender Belegung von 42 Hz und 100 Hz-\n\nGleisstromkreisen\n\nRegelfahrzeuge oder schwere Nebenfahrzeuge, welche die Gleisfreimeldeanlagen\n\nder 42 Hz oder 100 Hz-Gleisstrom-Technik (Bauform WSSB) wÃ¤hrend der Fahrt\n\nnicht zuverlÃ¤ssig erkennen kÃ¶nnen, werden als \"Fahrzeuge mit unzureichender Belegung von 42 Hz und 100 Hz-Gleisstromkreisen\" bezeichnet.\n\nFehlleitung, fehlleiten\n\nEin Zug wird fehlgeleitet, wenn er in einen Fahrweg eingelassen wird, der nicht seinem Fahrplan oder seinem Auftrag entspricht.\n\nFlankenschutzeinrichtungen\n\nFlankenschutzeinrichtungen sind signaltechnische Einrichtungen, die Fahrten auf\n\nFahrstraÃŸen gegen Fahrzeugbewegungen schÃ¼tzen.\n\nZu den Flankenschutzeinrichtungen gehÃ¶ren Weichen, Gleissperren, Sperrsignale,\n\nHauptsignale ohne Signal Zs 103, Signale Ra 11 (DS 301) mit Lichtsignal Sh 1,\n\nsofern technisch ausgeschlossen ist, dass das Signal Sh 1 erteilt werden kann, solange das Wartezeichen als Flankenschutz fÃ¼r eine Zugfahrt dient, Signale Ra 11 a\n\n(DV 301) und alleinstehende Signale Ne 14.\n\nFlankenschutzraum\n\nFlankenschutzraum ist der Raum zwischen einer Flankenschutzeinrichtung oder einem Signal Ne 14 und dem Grenzzeichen einer Weiche oder Kreuzung im Fahrweg\n\noder Durchrutschweg.",226,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":12,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","cdf06d28cb88c4df045f9b323bf00167031a96cbe97994e85832a8c905698741"],["chunk_b9a026129474b24db7d6ce46","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",20,"Seite 12","FÃ¼hrungsgrÃ¶ÃŸenï€ \n\nSollgeschwindigkeit, Zielgeschwindigkeit und Zielentfernung werden bei anzeigegefÃ¼hrten ZÃ¼gen als FÃ¼hrungsgrÃ¶ÃŸen bezeichnet und im FÃ¼hrerraum angezeigt.\n\nFS (Full Supervision)\n\nBetriebsart bei ETCS, bei der ein Zug in VollÃ¼berwachung fÃ¤hrt, und zwar mit einer\n\nETCS-Fahrterlaubnis, die ETCS dem Tf mit FÃ¼hrungsgrÃ¶ÃŸen und einem Symbol in\n\nder FÃ¼hrerraumanzeige anzeigt.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",52,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":12,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","b997fe42bd1d8298d87bd1c376fc254033d188968ddb906b0bba471993957c22"],["chunk_bc3efb068718b647b7010ebc","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",21,"Seite 13","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 7\n\nGegengleis\n\nDas Gleis, das auf zweigleisiger, freier Strecke entgegen der gewÃ¶hnlichen Fahrtrichtung befahren wird, wird als Gegengleis bezeichnet.\n\nGelenkwagen\n\nGelenkwagen sind Wagen, die aus mehreren Wagenelementen bestehen, die untereinander durch ein Gelenk verbunden sind. Gelenkwagen haben nur eine Wagennummer.\n\nGeschobene ZÃ¼ge\n\nGeschobene ZÃ¼ge sind ZÃ¼ge, in denen kein arbeitendes Triebfahrzeug an der\n\nSpitze lÃ¤uft oder von der Spitze aus gesteuert wird.\n\nZÃ¼ge, die aus einem Nebenfahrzeug mit Kraftantrieb und einem vorangestellten Nebenfahrzeug ohne Kraftantrieb oder aus einem Triebfahrzeug und einem vorangestellten SchneerÃ¤umfahrzeug gebildet sind, sind keine geschobenen ZÃ¼ge, wenn\n\ndie Fahrzeuge eine bauartkompatible Einheit bilden.\n\nGewÃ¶hnlicher Halteplatz\n\nDer gewÃ¶hnliche Halteplatz ist die Stelle, an der ein Zug bei einem planmÃ¤ÃŸigen\n\nHalt dem Zweck des Haltes entsprechend halten muss. Im Einzelnen gilt Folgendes:\n\nDer gewÃ¶hnliche Halteplatz eines Reisezuges mit Betriebshalt oder eines GÃ¼terzuges ist mÃ¶glichst nahe am Halt gebietenden Signal, vor dem LZB-Halt bzw. vor dem\n\nETCS-Halt.\n\nDer gewÃ¶hnliche Halteplatz eines Reisezuges mit Regelhalt oder Bedarfshalt ist am\n\nBahnsteig, hierbei mÃ¼ssen sich in der Regel alle fÃ¼r Reisende zum Ein- und Aussteigen vorgesehenen TÃ¼ren am Bahnsteig befinden.\n\nDie Regeln zum gewÃ¶hnlichen Halteplatz gelten nicht fÃ¼r Halte zum Sichern eines\n\nBahnÃ¼berganges.\n\nGleiswechselbetrieb\n\nGleiswechselbetrieb ist eingerichtet, wo das Gegengleis mit Hauptsignal und Signal\n\nZs 6 befahren werden kann. Gleiswechselbetrieb kann stÃ¤ndig oder vorÃ¼bergehend\n\neingerichtet sein. VorÃ¼bergehend eingerichteter Gleiswechselbetrieb wird in einer\n\nBetra angeordnet.\n\nGrenze zwischen Bahnhof und freier Strecke",231,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":13,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","055a4168727d6a3896e3b00a9d246ad474a8926b183e682ada0002423bd208c7"],["chunk_73155346f253e30e0401a07d","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",22,"Seite 13","Als Grenze zwischen den BahnhÃ¶fen und der freien Strecke gelten im Allgemeinen\n\ndie Einfahrsignale bzw. die sie ersetzenden Signale Ne 14 oder Trapeztafeln, sonst\n\ndie Einfahrweichen. Bei besonderen Ã¶rtlichen VerhÃ¤ltnissen kann die Grenze anderweitig festgelegt sein. Bahnhofsgleise und andere Anlagen neben den durchgehenden Hauptgleisen, die Ã¼ber die Grenze hinausreichen, gehÃ¶ren zu den Bahnhofsanlagen.\n\nGrenzsignal\n\nEin Grenzsignal ist ein Hauptsignal oder Vorsignal, an dem eine Strecke mit ETCS\n\nbeginnt oder endet.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",75,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":13,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","1ad623443b64920395b11fbf666b20d1a6c292d0ed5a46c4b121ae305ed6d459"],["chunk_faf940bbd3b8d8a42ef85f4a","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",23,"Seite 14","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 8\n\nHalt zum Sichern eines BahnÃ¼berganges\n\nEin Halt zum Sichern eines BahnÃ¼berganges ist ein Fahrplanhalt, bei dem ein Zug\n\nvor dem BahnÃ¼bergang anhalten muss, weil der BahnÃ¼bergang planmÃ¤ÃŸig durch\n\nZugpersonal oder durch andere Mitarbeiter gesichert werden muss.\n\nHaltepunkte\n\nHaltepunkte sind Bahnanlagen ohne Weichen, wo ZÃ¼ge planmÃ¤ÃŸig halten, beginnen oder enden dÃ¼rfen.\n\nHaltestellen\n\nHaltestellen sind Abzweigstellen, Ãœberleitstellen oder Anschlussstellen, die mit einem Haltepunkt Ã¶rtlich verbunden sind.\n\nHauptgleise\n\nHauptgleise sind die von ZÃ¼gen planmÃ¤ÃŸig befahrenen Gleise.\n\nIS (Isolation)\n\nBetriebsart bei ETCS, wenn das ETCS-FahrzeuggerÃ¤t mit dem StÃ¶rschalter ausgeschaltet ist. Es sind keine Eingaben und Anzeigen Ã¼ber die Fahrzeugeinrichtung\n\nmÃ¶glich. Der Zug kann ohne ETCS-Fahrterlaubnis fahren.\n\nKleinwagen\n\nKleinwagen sind Nebenfahrzeuge, die Gleisschaltmittel oder Gleisfreimeldeanlagen\n\nnicht zuverlÃ¤ssig beeinflussen.\n\nKleinwagenfahrten\n\nKleinwagenfahrten sind Fahrten, die aus Kleinwagen gebildet sind oder in die Kleinwagen eingestellt sind. Sie dÃ¼rfen nur als Sperrfahrt oder Rangierfahrt verkehren.\n\nKleinwagenfahrten als Sperrfahrten sind nach den Regeln fÃ¼r Zugfahrten unter Beachtung der fÃ¼r Kleinwagenfahrten geltenden Besonderheiten durchzufÃ¼hren.\n\nKleinwagenfahrten als Rangierfahrten sind nach den Regeln fÃ¼r das Rangieren unter Beachtung der fÃ¼r Kleinwagen geltenden Besonderheiten durchzufÃ¼hren.\n\nKontaktstelle\n\nKontaktstelle ist:\n\na) die Zugmeldestelle, die wÃ¤hrend der Arbeitsunterbrechung der Ã¼berwachenden Zugmeldestelle bei der Notfallleitstelle fÃ¼r ein der Ã¼berwachenden Zugmeldestelle zugeordnetes, gesperrtes Gleis Hilfe aufrufen muss,\n\nb) die Betriebsstelle, die die Meldungen zu Arbeitsende und Arbeitsbeginn",213,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":14,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","15c9dd83ec01551d365d2013388defbe4a431d9154e2539c55bffa487e085981"],["chunk_aa7ee825d6bf882cb1fd7001","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",24,"Seite 14","bei unterbrochener Arbeitszeit entgegennimmt und der Besonderheiten\n\nwÃ¤hrend der unterbrochenen Arbeitszeit gemeldet werden.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",18,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":14,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","c93dad5e3fe184ffcf4e919ea78d88fc837b0d13df6848bd1f7e0a8697c75c3a"],["chunk_ed473790e2b9286c2a00ae7d","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",25,"Seite 15","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 9\n\nKreuzen\n\nBeim Kreuzen wartet ein Zug auf einer Zugmeldestelle, weil der Zugfolgeabschnitt,\n\nin den er eingelassen werden soll, noch durch einen in der Gegenrichtung fahrenden Zug beansprucht wird.\n\nLS (Limited Supervision)\n\nLimited Supervision (LS) ist eine ETCS-Betriebsart im ETCS-Level 1. Es werden\n\ndie Signalinformationen Ã¼ber schaltbare Balisen an das ETCS-FahrzeuggerÃ¤t des\n\nZuges Ã¼bertragen. In der ETCS-Betriebsart LS werden keine FÃ¼hrungsgrÃ¶ÃŸen angezeigt. Die ZÃ¼ge fahren signalgefÃ¼hrt.\n\nMitarbeiter\n\nMitarbeiter, im Sinne des bahnbetrieblichen Regelwerks, sind Personen, die TÃ¤tigkeiten im Bahnbetrieb selbststÃ¤ndig nur verrichten dÃ¼rfen, wenn sie fÃ¼r diese TÃ¤tigkeiten geprÃ¼ft und mit ihrer AusfÃ¼hrung beauftragt sind.\n\n* Mehrkraft-Tfz\n\n*\n\n* Mehrkraft-Tfz sind Triebfahrzeuge mit mehr als einer Antriebsart. Sie kÃ¶nnen so-\n\n* wohl fahrdrahtunabhÃ¤ngig oder mit gehobenem Stromabnehmer verkehren. Sie\n\n* werden unterschieden nach Triebfahrzeugen mit â€žLast-Mile-Paketâ€œ (vollwertiger\n\n* Elektroantrieb mit Diesel-Hilfsmotor zur ÃœberbrÃ¼ckung kurzer Abschnitte ohne Fahr-\n\n* draht) und kombinierten Triebfahrzeugen mit mehreren vollwertigen Antriebssyste-\n\n* men, die ohne Wechsel des Triebfahrzeuges fahrdrahtunabhÃ¤ngig und mit gehobe-\n\n* nem Stromabnehmer ZÃ¼ge vom Anfangs- bis zum Endbahnhof befÃ¶rdern kÃ¶nnen.\n\n* Werden mehrere arbeitende Triebfahrzeuge, von denen mindestens jeweils eines\n\n* fahrdrahtunabhÃ¤ngig und eines mit gehobenem Stromabnehmer verkehren kann,\n\n* mit Mehrfachtraktionssteuerung gefahren, gelten diese ebenfalls als Mehrkraft-Tfz.\n\nNachgeschobene ZÃ¼ge\n\nNachgeschobene ZÃ¼ge sind ZÃ¼ge, in denen mindestens ein arbeitendes Triebfahrzeug an der Spitze lÃ¤uft oder von der Spitze aus gesteuert wird und in denen bis zu",228,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":15,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","2ad007e1342b15a1221baf49b64521c7322c2bd7623b907d116b18af2bf842fe"],["chunk_9e720032fe5b90db8e3c5134","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",26,"Seite 15","zwei arbeitende Triebfahrzeuge laufen, die nicht von der Spitze aus gesteuert werden.\n\nNebenfahrzeuge\n\nNebenfahrzeuge werden unterschieden in Nebenfahrzeuge mit Kraftantrieb und in\n\nNebenfahrzeuge ohne Kraftantrieb. Bestimmungen fÃ¼r Triebfahrzeuge gelten auch\n\nfÃ¼r Nebenfahrzeuge mit Kraftantrieb, sofern es nicht im Einzelfall anders bestimmt\n\nist.\n\nNebengleise\n\nNebengleise sind Gleise, die planmÃ¤ÃŸig nicht von ZÃ¼gen befahren werden.\n\nNL (Non Leading)\n\nBetriebsart bei ETCS, die der Tf der Zuglokomotive bei Vorspann bzw. eines mit\n\ndem Zug gekuppelten Schiebetriebfahrzeuges wÃ¤hlen muss.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",80,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":15,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","445911ddf8b4a0bf93463e577bcf3e8fb2af2ae5c9acc217591033bed809429c"],["chunk_5bf7221d77f4e8b398c44ad1","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",27,"Seite 16","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 10\n\nNotbremsÃ¼berbrÃ¼ckungsabschnitt\n\nEin NotbremsÃ¼berbrÃ¼ckungsabschnitt ist ein durch NBÃœ-Kennzeichen gekennzeichneter Abschnitt, in dem ZÃ¼ge bei einer Notbremsung nicht anhalten sollen.\n\nNP (No Power)\n\nBetriebsart bei ETCS, in die das ETCS-FahrzeuggerÃ¤t wechselt, wenn die Stromversorgung ausgeschaltet ist.\n\nOrtsstellbereich\n\nEin Ortsstellbereich ist ein Bereich in Nebengleisen mit ortsgestellten Weichen und\n\nGleissperren, in dem ausschlieÃŸlich rangiert wird. Die Weichen und Gleissperren\n\nwerden einzeln ggf. in Gruppen (elektrischer Antrieb) umgestellt. Die Bedienung erfolgt durch das Rangierpersonal. Zug- und RangierstraÃŸen sind nicht vorhanden.\n\nEin fÃ¼r eine Rangierfahrt Halt gebietendes Signal begrenzt Ortsstellbereiche nach\n\nauÃŸen. Der Beginn eines Ortsstellbereiches kann durch ein Orientierungszeichen\n\nnach Ril 301.9001 gekennzeichnet sein.\n\nOS (On Sight)\n\nBetriebsart bei ETCS, bei der ein Zug auf Sicht fahren muss, und zwar mit einer\n\nETCS-Fahrterlaubnis, die dem Tf mit einem Symbol in der FÃ¼hrerraumanzeige angezeigt wird. ETCS Ã¼berwacht die maximal zulÃ¤ssige Geschwindigkeit fÃ¼r Fahren\n\nauf Sicht und das Ende der ETCS-Fahrterlaubnis.\n\nOverride EOA\n\nFunktion im ETCS-FahrzeuggerÃ¤t, die es dem Tf ermÃ¶glicht, aus den ETCS-Betriebsarten FS, OS oder LS in die ETCS-Betriebsart SR zu wechseln sowie an einem ETCS-Halt vorbeizufahren.\n\nPlanmÃ¤ÃŸige Halte\n\nEin planmÃ¤ÃŸiger Halt kann:\n\n- als Fahrplanhalt im Fahrplan bzw. in einer Fahrplananordnung angeordnet sein\n\noder\n\n- als zusÃ¤tzlicher Halt angeordnet werden. Diese Anordnung darf das Eisenbahnverkehrsunternehmen erteilen.\n\nPT (Post Trip)\n\nBetriebsart bei ETCS, in die das ETCS-FahrzeuggerÃ¤t wechselt, nachdem der Tf im\n\nStillstand die Betriebsart TR bestÃ¤tigt hat.\n\nRangierabteilung",230,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":16,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","39fbef5d3722c275fdf39d1f5385aca35667c009b4f2b3e2761131d9e8626e75"],["chunk_ff08374b7ce30060bd566755","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",28,"Seite 16","Ein angetriebenes Fahrzeug, das mit anderen Fahrzeugen gekuppelt sein kann und\n\nzum Rangieren bestimmt ist.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",20,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":16,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","a46d9c479cf49dc74b706161def0e381d7bbcf4061450ca026e9e128bec538b5"]]');
