INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_9131e8a75a9cf7484b36d336","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",29,"Seite 17","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 11\n\nRangieren\n\nRangieren ist das Bewegen von Fahrzeugen im Bahnbetrieb, ausgenommen das\n\nFahren der ZÃ¼ge. Das Bewegen von Fahrzeugen im Baugleis ist Rangieren. Beim\n\nRangieren wird nach folgenden Fahrzeugbewegungen unterschieden:\n\n- Rangierfahrt,\n\n- AbdrÃ¼cken, Ablaufen,\n\n- AbstoÃŸen,\n\n- BeidrÃ¼cken,\n\n- AufdrÃ¼cken und\n\n- Verschieben.\n\nRangierfahrt\n\nEine Rangierfahrt ist eine bewegte Rangierabteilung.\n\nRBC (Radio Block Centre)\n\nSiehe Begriff â€žETCS-Zentraleâ€œ.\n\nRegelfahrzeuge\n\nRegelfahrzeuge werden unterschieden nach Triebfahrzeugen und Wagen.\n\nRegelgleis\n\nDas Gleis, das auf zweigleisiger, freier Strecke in der gewÃ¶hnlichen Fahrtrichtung\n\nbefahren wird, wird als Regelgleisbezeichnet.\n\nRegelhalt\n\nEin Regelhalt ist ein Fahrplanhalt, bei dem ein Zug auf der Betriebsstelle halten\n\nmuss.\n\nRegelzÃ¼ge\n\nRegelzÃ¼ge sind ZÃ¼ge, die nach einem im Voraus festgelegten Fahrplan tÃ¤glich oder\n\nan bestimmten Tagen verkehren.\n\nRelease Speed\n\nDie Release Speed erlaubt in ETCS-Level 1 die Fahrt bis zu dem Signal mit der\n\nBalisengruppe, die der ETCS-Fahrzeugeinrichtung eine neue ETCS-Fahrterlaubnis\n\nÃ¼bermittelt.\n\nIn ETCS-Level 2 dient die Release Speed dem Ausgleich der Ungenauigkeiten der\n\nWegmessung, indem sie es ermÃ¶glicht, bis zum zugehÃ¶rigen Hauptsignal, Sperrsignal, Signal Ne 14, Blockkennzeichen oder Gleisabschluss vorzufahren.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",178,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":17,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","b84724b6abfebde77b7a4a0a89ec76a8b787dd16ca85cc45be3fae4adf2f9405"],["chunk_82ea6d53796230a2d441c704","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",30,"Seite 18","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 12\n\nSB (Stand By)\n\nBetriebsart bei ETCS, bei der die ETCS-Fahrzeugeinrichtung in Bereitschaft ist und\n\ndie dem Tf durch ein Symbol in der FÃ¼hrerraumanzeige angezeigt wird. In der Betriebsart SB ist der Zug noch ohne ETCS-Fahrterlaubnis.\n\nSF (System Failure)\n\nBetriebsart bei ETCS, in die die ETCS-Fahrzeugeinrichtung bei sicherheitsrelevanten Fehlern wechselt. Gleichzeitig leitet die ETCS-Fahrzeugeinrichtung eine\n\nZwangsbremsung ein.\n\nSchneerÃ¤umfahrten\n\nSchneerÃ¤umfahrten sind Fahrten mit arbeitenden SchneerÃ¤umern â€“ auÃŸer Fahrten\n\nmit SchneepflÃ¼gen, die mit dem Triebfahrzeug fest verbunden sind.\n\nSelbsttÃ¤tige Blockstellen\n\nSelbsttÃ¤tigeï€ Blockstellen sind Blockstellen der freien Strecke, wo selbsttÃ¤tiger Streckenblock eingerichtet ist, ausgenommen Abzweigstellen oder Ãœberleitstellen.\n\nSelbststellbetrieb, Zuglenkung\n\nBei Selbststellbetrieb oder bei Zuglenkung mit Lenkplan werden ZugstraÃŸen selbsttÃ¤tig eingestellt.\n\nSH (Shunting)\n\nBetriebsart bei ETCS, bei der ein Zug oder eine Rangierfahrt ohne ETCS-Fahrterlaubnis fahren kann und die ETCS dem Tf durch ein Symbol in der FÃ¼hrerraumanzeige anzeigt; die Erlaubnis zur Fahrt erhÃ¤lt der Tf durch einen Befehl bzw. beim\n\nRangieren durch Zustimmung des Ww.\n\nSignalgefÃ¼hrt\n\nZÃ¼ge sind signalgefÃ¼hrt, wenn sie nicht anzeigegefÃ¼hrt sind.\n\nSollgeschwindigkeit\n\nDie Sollgeschwindigkeit ist die als V-soll angezeigte Geschwindigkeit fÃ¼r einen anzeigegefÃ¼hrten Zug, mit der ein Zug fahren kann, ohne dass LZB oder ETCS eine\n\nWarnung ausgibt oder eine Bremsung einleitet.\n\nSperrfahrten\n\nSperrfahrten sind ZÃ¼ge oder Kleinwagenfahrten, die in ein Gleis der freien Strecke\n\neingelassen werden, das gesperrt ist.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",218,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":18,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","5d98ada0eb1887f3f0065989b421301b1ed9dcffdb01ae4b21797573b92ca432"],["chunk_4b20375c1e1d874b29cb636e","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",31,"Seite 19","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 13\n\nSR (Staff Responsible)\n\nBetriebsart bei ETCS, bei der ETCS die zulÃ¤ssige Geschwindigkeit fÃ¼r SR und das\n\nEnde der Erlaubnis zur Fahrt durch Balisen mit der Information â€žHalt fÃ¼r ZÃ¼ge in\n\nETCS-Betriebsart SRâ€œ am Signal Ne 14 Ã¼berwacht. ETCS zeigt dem Tf die Betriebsart SR durch ein Symbol in der FÃ¼hrerraumanzeige an. Die Erlaubnis zur Fahrt erhÃ¤lt der Tf durch einen Befehl, bei ETCS-Level 1 auch durch ein Signal oder bei\n\nETCS-Level 2 auch durch eine Textmeldung.\n\nStandort des Zuges\n\nDer Standort des Zuges ist die mÃ¶glichst genaue Angabe der Stelle, an der sich die\n\nSpitze des Zuges beim Halten befindet. WÃ¤hrend der Fahrt ist der Standort die aktuelle Position des Zuges.\n\nBeispiele: â€žAsig P1 in Gleis 1 des Bf Kleinstadtâ€œ oder â€žin km 29,4 im Regelgleis von\n\nKleinstadt nach Erleâ€œ.\n\nStrecken mit Stichstreckenblock\n\nStrecken mit Stichstreckenblock sind eingleisige Stichstrecken, die mit Streckenblock ausgerÃ¼stet sind und nur aus einem Zugfolgeabschnitt bestehen. Dabei befinden sich alle Bedieneinrichtungen des Stichstreckenblocks auf der angrenzenden\n\nZugmeldestelle.\n\nTR (Trip)\n\nBetriebsart bei ETCS, in die das ETCS-FahrzeuggerÃ¤t nach Ãœberfahren eines\n\nETCS-Haltes oder in bestimmten StÃ¶rsituationen wechselt.\n\nTriebfahrzeuge\n\nTriebfahrzeuge sind Lokomotiven, Triebwagen, TriebkÃ¶pfe und TriebzÃ¼ge sowie\n\nKleinlokomotiven.\n\nTriebfahrzeugfÃ¼hrer\n\nMitarbeiter eines Eisenbahnverkehrsunternehmens, die zum selbststÃ¤ndigen FÃ¼hren und Bedienen von Triebfahrzeugen befugt sind.\n\nÃœberholen\n\nBeim Ãœberholen fÃ¤hrt ein Zug an einem anderen Zug derselben Fahrtrichtung vorbei.\n\nÃœberleitstellen\n\nÃœberleitstellen sind Blockstellen der freien Strecke, wo ZÃ¼ge auf ein anderes Gleis",234,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":19,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","0bfd45ea298d1b63c1f911a656d9595fabbdad1c34a0c48205e96af0bcf5e5d6"],["chunk_c661a67820f386f04d1ddc8c","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",32,"Seite 19","derselben Strecke Ã¼bergehen kÃ¶nnen. Eine Ãœberleitstelle wird durch ihre Blocksignale begrenzt. Bestimmungen fÃ¼r Abzweigstellen gelten auch fÃ¼r Ãœberleitstellen,\n\nsofern es nicht im Einzelfall anders bestimmt ist.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",31,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":19,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","26b705f07f4e218afc41ad3fcc2c49eacfe0c04ea081f8e9ce402762eb17ac4d"],["chunk_23aee04efc0f410b673e73c5","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",33,"Seite 20","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 14\n\nÃœberwachende Zugmeldestelle\n\nÃœberwachende Zugmeldestelle ist die in einer Betra bezeichnete Zugmeldestelle,\n\nab der ein Gleis der freien Strecke wÃ¤hrend unterbrochener Arbeitszeit gesperrt\n\nwerden soll.\n\nUmleiten\n\nBeim Umleiten fÃ¤hrt ein Zug Ã¼ber eine andere als die im Fahrplan angegebene Strecke.\n\nUN (Unfitted)\n\nBetriebsart bei ETCS, die nur im ETCS-Level 0 mÃ¶glich ist. In der Betriebsart UN\n\nliest das ETCS-FahrzeuggerÃ¤t die Balisen und kann eine Verbindung zur ETCS-\n\nZentrale aufbauen. Das FahrzeuggerÃ¤t Ã¼berwacht die zulÃ¤ssige Geschwindigkeit\n\nvon 50 km/h bei nicht wirksamer Zugbeeinflussung.\n\nVerkehrliche Abfahrtszeit\n\nDie verkehrliche Abfahrtszeit ist die fÃ¼r eine Betriebsstelle in den Auskunftsmedien\n\nund in den Fahrgastinformationen am Bahnsteig verÃ¶ffentlichte Zeit. Die verkehrliche Abfahrtszeit ist fÃ¼r den Reisenden die maÃŸgebliche Zeit.\n\nVerlassensfeststellung\n\nDie Verlassensfeststellung umfasst die PrÃ¼fung, dass Zugfolgeabschnitte oder einzelne Gleisabschnitte von Fahrzeugen gerÃ¤umt sind. Bei der Verlassensfeststellung\n\nwird das Freisein durch das Auswerten der ordnungsgemÃ¤ÃŸ wirkenden Einrichtungen des Streckenblocks oder der Gleisfreimeldeanlage oder, wo diese nicht vorhanden sind, durch das Auswerten von EintrÃ¤gen und Meldungen geprÃ¼ft.\n\nVerschieben\n\nVerschieben ist das Bewegen von Fahrzeugen durch Menschenkraft oder durch einen Antrieb, der nicht von einem Triebfahrzeug ausgeht.\n\nVersuchsfahrten\n\nVersuchsfahrten sind Fahrten, die nach abweichenden Regeln verkehren. Diese\n\nsind in einer Fahrplananordnung gegeben.\n\nVirtuelle Blockstelle\n\nVirtuelle Blockstellen gibt es auf Streckenabschnitten mit ETCS oder LZB. Sie sind\n\neingerichtet:\n\n- auf Strecken mit ETCS-Level 2 ohne Hauptsignale an allen Signalen Ne 14.",226,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":20,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","7fbbbc7d44c0730ba769d0d38c386af7b8636d2b98a87be49da7eb58e5a581c2"],["chunk_1166398f8630d182d7ff3db8","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",34,"Seite 20","- an Blockkennzeichen.\n\nBei LZB sind virtuelle Blockstellen auÃŸerdem eingerichtet fÃ¼r Fahrten auf dem Gegengleis in HÃ¶he des Blocksignals einer Abzweigstelle oder in HÃ¶he des Einfahrsignals eines Bahnhofs.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",33,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":20,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","7f7bdc7f653e01f10d5f7e50dc198c46e0b5feb119151444af0a12c7bd35f3b6"],["chunk_ad0eb9ec186853a45d94f371","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",35,"Seite 21","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 15\n\nVorspann\n\nVorspann ist die Bespannung eines Zuges mit zwei Lokomotiven, die mit je einem\n\nTf besetzt sind. Die Vorspannlokomotive befindet sich an der Spitze des Zuges.\n\nWagen\n\nWagen werden eingeteilt in:\n\n- Reisezugwagen; hierzu zÃ¤hlen Personen-, ReisezuggepÃ¤ck-, Autoreisezugund Postwagen\n\n- GÃ¼terwagen.\n\nWageneinheiten\n\nWageneinheiten sind aus mehreren Einzelwagen stÃ¤ndig gekuppelte Einheiten, die\n\nim Betrieb nicht getrennt werden kÃ¶nnen und von denen jeder Einzelwagen mit einem Laufwerk ausgerÃ¼stet ist. Wageneinheiten haben nur eine Wagennummer und\n\nenthalten Anschriften fÃ¼r nur einen Wagen.\n\nWeichenwÃ¤rter\n\nWw wirken bei der DurchfÃ¼hrung des Rangierens mit. Sie verstÃ¤ndigen beim Rangieren Tf, Rangierbegleiter, benachbarte Ww, SchrankenwÃ¤rter oder Fdl. Sie stimmen beim Rangieren Fahrzeugbewegungen zu. VerstÃ¤ndigung und Zustimmung\n\nentfallen, wenn in Ortsstellbereichen rangiert wird.\n\nWw kÃ¶nnen an der DurchfÃ¼hrung von Zugfahrten beteiligt sein.\n\nFdl und Ww sind in den Richtlinien zusammenfassend in Kurzform auch als â€žBedienerâ€œ angesprochen.\n\nWendezÃ¼ge\n\nWendezÃ¼ge sind vom FÃ¼hrerraum an der Spitze aus gesteuerte ZÃ¼ge, deren\n\nTriebfahrzeuge beim Wechsel der Fahrtrichtung den Platz im Zuge beibehalten.\n\nZielentfernung\n\nDie Zielentfernung ist die Entfernung zum Ort, an dem die Geschwindigkeit eines\n\nZuges gleich oder niedriger sein muss als die vorgegebene Zielgeschwindigkeit.\n\nZielgeschwindigkeit\n\nDie Zielgeschwindigkeit ist die Geschwindigkeit, die am durch die Zielentfernung\n\nvorgegebenen Ort erreicht sein muss. Die Zielgeschwindigkeit 0 km/h zeigt einen\n\nzu erwartenden LZB-Halt oder ETCS-Halt an.\n\nZufahrtsicherungssignal\n\nEin Zufahrtsicherungssignal ist das letzte Hauptsignal vor einer Strecke mit ETCS-",227,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":21,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","bc4e57daa616dad85f0192dd857c45d31a921e10a1a2d3b0e79eb724b540cacc"],["chunk_d073758b132eaa0beca3cd94","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",36,"Seite 21","Level 2 ohne Hauptsignale. Innerhalb dieser Strecke mit ETCS-Level 2 ohne Hauptsignale kann ein zusÃ¤tzliches Hauptsignal zur Fahrt in einen Bereich ohne ETCS-\n\nAusrÃ¼stung vorhanden sein.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",31,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":21,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","055ddc63e75f4891a4092d43ac8e75e90fa57b5cca04dbccdc940c7cfdf6ca2f"],["chunk_3f22a0826291104da55142f4","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",37,"Seite 22","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 16\n\nZÃ¼ge\n\nDas Bewegen von ZÃ¼gen sind Zugfahrten. ZÃ¼ge sind auf die freie Strecke Ã¼bergehende oder innerhalb eines Bahnhofs nach einem Fahrplan verkehrende einzeln\n\nfahrende Triebfahrzeuge oder Einheiten, die zusammengesetzt sein kÃ¶nnen aus\n\narbeitenden Triebfahrzeugen oder arbeitenden Triebfahrzeugen und dem Wagenzug, in den Wagen oder nicht arbeitende Triebfahrzeuge eingestellt sind.\n\nGeeignete Nebenfahrzeuge dÃ¼rfen wie ZÃ¼ge behandelt oder in ZÃ¼ge eingestellt\n\nwerden. Das Eisenbahnverkehrsunternehmen gibt dem Zugpersonal bekannt, welche Nebenfahrzeuge fÃ¼r ZÃ¼ge geeignet sind.\n\nZÃ¼ge werden in Reise- und GÃ¼terzÃ¼ge eingeteilt.\n\nZÃ¼ge des Gelegenheitsverkehrs\n\nZÃ¼ge des Gelegenheitsverkehrs sind ZÃ¼ge, die auf besondere Anordnung an bestimmten Tagen:\n\n- nach einem im Voraus festgelegten und bekannt gegebenen Fahrplan (BedarfszÃ¼ge) oder\n\n- nach einem von Fall zu Fall besonders aufgestellten Fahrplan\n\nverkehren.\n\nZugfahrt mit besonderem Auftrag\n\nEine Zugfahrt mit besonderem Auftrag ist eine Zugfahrt, die der Fdl nicht durch\n\nFahrtstellung eines Hauptsignals oder einem daraus abgeleiteten Auftrag LZB-Fahrt\n\nbzw. einer ETCS-Fahrterlaubnis in der ETCS-Betriebsart FS zulassen kann oder\n\ndarf. An einer virtuellen Blockstelle entspricht der Fahrtstellung des Hauptsignals\n\nder entsprechende Fahrtmelder.\n\nZugfolgeabschnitte\n\nZugfolgeabschnitte sind Gleisabschnitte der freien Strecke, in die ein Zug nur eingelassen werden darf, wenn sie frei von Fahrzeugen sind und das Gleis bis zur\n\nnÃ¤chsten Zugmeldestelle nicht durch einen Zug der Gegenrichtung beansprucht\n\nwird. Es gibt Zugfolgeabschnitte fÃ¼r signalgefÃ¼hrte ZÃ¼ge und fÃ¼r anzeigegefÃ¼hrte\n\nZÃ¼ge.\n\nZugfolgestellen\n\nZugfolgestellen begrenzen Zugfolgeabschnitte und regeln die Folge der ZÃ¼ge auf",228,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":22,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","5ba5af6374d5f57842d6871f3403901121f998d62875064d6068884fd5020338"],["chunk_7c65bf44c8e08b5b396510d1","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",38,"Seite 22","der freien Strecke. Es gibt Zugfolgestellen fÃ¼r signalgefÃ¼hrte ZÃ¼ge und fÃ¼r anzeigegefÃ¼hrte ZÃ¼ge.\n\nZugmeldestellen\n\nZugmeldestellen sind diejenigen Zugfolgestellen, die die Reihenfolge der ZÃ¼ge auf\n\nder freien Strecke regeln. BahnhÃ¶fe, Abzweigstellen und Ãœberleitstellen sind stets\n\nZugmeldestellen.\n\nZugpersonal\n\nDas Zugpersonal besteht aus dem Tf und weiterem mit sonstigen betrieblichen Aufgaben im Zug betrautem Personal des Eisenbahnverkehrsunternehmens.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",59,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":22,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","c4bb93c1cab5c196a75080f5f472231399de2bf7e870c3b55fe34e58cbfef56f"],["chunk_603c8aebc3ca3292e402feaf","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",39,"Seite 23","GrundsÃ¤tze; Begriffe 408.0055\n\nSeite 17\n\n3 Ã–rtliche Regeln im Streckenbuch\n\nKeine\n\nï±\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",17,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":23,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","0c5fd86f73935b0ff754f5f24a68d3bd6db3fb77e6111616c5b4a7e39c9ae2fc"],["chunk_f810c20daa0a78972b2715c4","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",40,"Seite 25","Richtlinie\n\nBahnbetrieb Fahrdienstvorschrift\n\nZÃ¼ge fahren; ErlÃ¤uterungen zu den Fahrplanangaben 408.2341A01\n\nSeite 1\n\n1 Allgemeines\n\nIn den Fahrplanangaben kÃ¶nnen die in den folgenden Abschnitten beschriebenen\n\nInhalte enthalten sein. Die Regeln der nachfolgenden Abschnitte beschreiben bzw.\n\nerlÃ¤utern die entsprechenden Fahrplanangaben des Buchfahrplans, z. B. als geschlossene Darstellung, Blattfahrplan, Geschwindigkeitsheft und Fahrzeitenheft sowie Ersatzfahrplan.\n\nHinweis:\n\nWenn das Eisenbahnverkehrsunternehmen die Fahrplanangaben in einer selbst erstellten Unterlage verÃ¶ffentlicht, sind die Fahrplanangaben durch das Eisenbahnverkehrsunternehmen erlÃ¤utert.\n\n2 Kopfangaben\n\nDer Kopf des Fahrplans kann folgende Angaben enthalten:\n\na) Bezeichnung des Streckenabschnitts.\n\nb) Zugnummer, bei Sperrfahrten mit dem Zusatz â€žSperrfahrtâ€œ oder â€žSperrfahrt\n\nKlâ€œ vor der Zugnummer.\n\n* c) Baureihennummern der arbeitenden Triebfahrzeuge, bei Mehrkraft-Tfz kann\n\n* die Baureihennummer mit dem Zusatz (E) zur Fahrt mit gehobenem Strom-\n\n* abnehmer ergÃ¤nzt sein, ohne den Zusatz (E) verkehrt der Zug fahrdrahtun-\n\n* abhÃ¤ngig.\n\n*\n\nd) Angaben zur Stufenschaltung bei ZÃ¼gen, die mit Brennkrafttriebfahrzeugen\n\nbefÃ¶rdert werden. Es bedeuten: SG = Schnellgang, LG = Langsamgang.\n\n1. Der Tf muss ReisezÃ¼ge im Schnellgang fahren. Wenn er einen Reisezug\n\nausnahmsweise im Langsamgang fahren muss, ist angegeben z. B. â€žvon\n\n... bis ... LGâ€œ.\n\n2. Wenn bei GÃ¼terzÃ¼gen, die im Schnellgang gefahren werden, ein Klammervermerk fÃ¼r den Langsamgang angebracht ist, sind die im Fahrplan\n\nangegebenen zulÃ¤ssigen Geschwindigkeiten (Geschwindigkeitsspalte\n\nund Textspalte) und die Uhrzeiten (Ankunft- und Abfahrtspalten) auf den\n\nSchnellgang abgestimmt. Wenn der Fahrplan die Angabe â€žSG ... t GL (LG",225,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":25,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","b06bd2c006427b8a1feb7076ff46977a13979025a0019ccbd72a7c1760554749"],["chunk_d5de5b925c48f7478dcfe822","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",41,"Seite 25","... t GL)â€œ enthÃ¤lt, darf der Tf bei einer Ãœberschreitung der fÃ¼r den Schnellgang angegebenen Grenzlast eine hÃ¶here Last im Langsamgang nur befÃ¶rdern, wenn die Betriebszentrale dies angeordnet hat.\n\ne) Zuggattung.\n\nf) Verkehrstage\n\ng) Last (zulÃ¤ssiges Gewicht des Wagenzuges). Eine Grenzlast ist durch â€žGLâ€œ\n\nhinter der Lastangabe gekennzeichnet.\n\nh) Bei Triebwagen kann die Zusammensetzung der Einheit angegeben sein, z.\n\nB. â€žTfz 628.2 + 928.2â€œ.\n\ni) ZulÃ¤ssige LÃ¤nge des Zuges.\n\nj) Mindestbremshundertstel.\n\nFachautor: I.IBB 31; Ben Dederichs; Tel.: [E-Mail-Adresse entfernt] GÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",84,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":25,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","b70a3b76534cfb0c735b65b6ef549534dc9cb61ad6a596cc5684d33971f9f276"],["chunk_420569fd434b282c6ff1278d","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",42,"Seite 26","ZÃ¼ge fahren; ErlÃ¤uterungen zu den Fahrplanangaben 408.2341A01\n\nSeite 2\n\nk) Bremsstellung R/P oder G; bei R + WB ist â€žWBâ€œ angegeben.\n\nl) GrÃ¶ÃŸte zulÃ¤ssige Geschwindigkeit.\n\nm) NotbremsÃ¼berbrÃ¼ckung bei ReisezÃ¼gen.\n\nn) Abschnittsweise DurchfÃ¼hrung eines Zuges unter einer anderen Zugnummer (Doppelfahrplan).\n\no) Hinweis auf zweite Fahrplandarstellung des Zuges.\n\np) MaÃŸgebende Geschwindigkeitshefte.\n\nq) â€žMindestens 90 % der Achsen des Wagenzuges mÃ¼ssen gebremst seinâ€œ,\n\nggf. mit dem Zusatz â€žBei einem Gewicht des Wagenzuges von mehr als 800\n\nt mÃ¼ssen Bremshundertstel ausgerechnet werdenâ€œ.\n\nr) Streckenabschnitte, auf denen der Zug mit der angegebenen Last nachgeschoben werden muss.\n\ns) Hinweis auf Ã„nderungen des Fahrplans bei baubedingten Regelungen\n\n3 Angaben in den Kilometrierungsspalten (Buchfahrplan\n\nSpalte 1 bzw. 3b)\n\n(1) Die Kilometrierungsspalte (Buchfahrplan Spalte 1) kann folgende Angaben enthalten:\n\na) Stellen der Geschwindigkeitswechsel fÃ¼r die in der Geschwindigkeitsspalte\n\nangegebenen Geschwindigkeiten,\n\nb) Standorte der in der Textspalte genannten Vorsignale, alleinstehenden Vorsignaltafeln, Hauptsignale mit Vorsignalfunktion, Signale Lf 6, oder Ãœberwachungssignale mit einem um mehr als 5 % verkÃ¼rzten Bremswegabstand.\n\nDie Angaben zu a) oder b) sind durch weiÃŸe Schrift auf schwarzem Grund (invers) dargestellt, wenn die zugehÃ¶rige Geschwindigkeitsangabe in der Geschwindigkeitsspalte oder Textspalte invers dargestellt ist.\n\n(2) Kilometrierungsspalte 1 kann in die Spalten 1a und 1b unterteilt sein. Angaben\n\nin Spalte 1b sind kursiv gedruckt.\n\nDie Angaben in Spalte 1a gelten, wenn die GNT des fÃ¼hrenden Fahrzeugs\n\nnicht wirksam oder die Neigetechnik des Zuges gestÃ¶rt ist.\n\nDie Angaben in Spalte 1b gelten, wenn die GNT des fÃ¼hrenden Fahrzeugs",237,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":26,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","32054ff35efb56252f83d6fba775d91ea1ad9cf90dbdc73393629a8153f0af6f"],["chunk_c8163d85b948808da530dcdc","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",43,"Seite 26","und die Neigetechnik des Zuges wirksam ist.\n\n(3) Die Kilometrierungsspalte (Buchfahrplan Spalte 3b) kann folgende Angaben\n\nenthalten:\n\na) Lage der Betriebsstellen.\n\nb) Standorte der Signale nach Abschnitt 5 Absatz (2).\n\nc) Lage eines BahnÃ¼bergangs, wenn der Tf den Zug vor dem BahnÃ¼bergang\n\nanhalten muss, weil das Zugpersonal oder andere Mitarbeiter beim Zug den\n\nBahnÃ¼bergang planmÃ¤ÃŸig sichern mÃ¼ssen.\n\nd) Lage der LZB-Bereichskennungswechsel.\n\ne) Lage der Wechsel der Zugfunkbereiche.\n\nf) Begrenzung der SÃ¤gelinien.\n\ng) Beginn und Ende der in Textspalte dargestellten Tunnel.\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",85,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":26,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","1808b66842a5d38e3932ee044bf76c185eb4ff371fcf6941b97c592c7fc3371a"],["chunk_dd5501335321f597172520be","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",44,"Seite 27","ZÃ¼ge fahren; ErlÃ¤uterungen zu den Fahrplanangaben 408.2341A01\n\nSeite 3\n\nh) durch â€žÂ¥â€œ gekennzeichnete Stellen.\n\ni) KilometrierungssprÃ¼nge nach der Kilometrierung der Strecke. KilometrierungssprÃ¼nge werden, wo die fortlaufende Kilometrierung unterbrochen ist,\n\nmit Fehl- oder ÃœberlÃ¤ngen wie nachstehend dargestellt. Die FehllÃ¤nge besteht nur rechnerisch, die ÃœberlÃ¤nge ist tatsÃ¤chlich vorhanden. Im Beispiel\n\nbetrÃ¤gt der Abstand zwischen Kilometerzeichen 48,2 und 48,4 nicht 200 m,\n\nsondern 600 m (gerundet).\n\nBeispiel\n\nEine Kilometerangabe in Klammern bezieht sich auf eine befahrene Strecke,\n\nderen KilometrierungssprÃ¼nge wegen der KÃ¼rze des befahrenen Abschnitts\n\nnicht dargestellt werden.\n\n4 Angaben in der Geschwindigkeitsspalte (Buchfahrplan\n\nSpalte 2)\n\n(1) Die Geschwindigkeitsspalte enthÃ¤lt die zulÃ¤ssigen Geschwindigkeiten fÃ¼r die in\n\nder Kilometrierungsspalte angegebenen Abschnitte. Die zulÃ¤ssigen Geschwindigkeiten gelten fÃ¼r signalgefÃ¼hrte ZÃ¼ge. FÃ¼r anzeigegefÃ¼hrte ZÃ¼ge gelten sie\n\nnur in folgenden FÃ¤llen:\n\n- wenn ein Befehl oder die La es anordnet,\n\n- wenn ETCS bei ETCS-Level 2 die Textmeldung â€žAufnahme in FSâ€œ,\n\nâ€žEntering FSâ€œ, â€žAufnahme in OSâ€œ oder â€žEntering OSâ€œ anzeigt.\n\n(2) Auf Strecken mit ETCS-Level 2 ohne Hauptsignale enthÃ¤lt die Geschwindigkeitsspalte die zulÃ¤ssige Geschwindigkeit fÃ¼r ZÃ¼ge in der ETCS-Betriebsart SR.\n\nNach dem Wechsel zu ETCS-Level NTC PZB/LZB gilt als zulÃ¤ssige Geschwindigkeit bis zum Grenzsignal die zum Zeitpunkt des Levelwechsels in der FÃ¼hrerraumanzeige angezeigte V-soll.\n\n(3) Wenn die zulÃ¤ssige Geschwindigkeit durch weiÃŸe Schrift auf schwarzem Grund\n\n(invers) dargestellt ist, wird sie nicht durch Signale angezeigt.\n\n(4) Die angegebene zulÃ¤ssige Geschwindigkeit gilt fÃ¼r das Regelgleis und fÃ¼r das",228,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\":27,\"source_id\":\"src_463e9f6aecb7902447e3\",\"source_sha256\":\"1a6a7d3a1e4194c99ce5d4c87dd5893b8fd6379fd0f9bc24a6cf024d47641b99\",\"source_version_id\":\"sv_de2416cd2eb5a35dc203e65d\"}","17d46654b9b8308378ca3c3b9e71529340e7460aaaf4b7c89958daae062fa6d2"],["chunk_08a37932356e4d5b564fd8dd","wiki/sources/ausnahme-239-ril-408-gueltig-ab-15-12-2025-data.md",45,"Seite 27","Gegengleis. Wenn im Gegengleis eine andere Geschwindigkeit gilt, ist sie in\n\nWinkel darunter angegeben.\n\nBeispiel\n\nGÃ¼ltig ab: 14.12.2025\n\nAusnahme 239",20,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/13374468/03f973e506a3706cf76933ea68fe92fa/Ausnahme-239-Ril-408-gueltig-ab-15-12-2025-data.pdf\",\"normalized_sha256\":\"14bf6011ad66029d490f9a783080e198aec13df84a4f7454829a77135a0ae5db\",\"page\"