INSERT INTO wiki_chunks (id,page_path,ordinal,heading_path,text,token_count,source_refs_json,content_sha) SELECT json_extract(value,'$[0]'),json_extract(value,'$[1]'),json_extract(value,'$[2]'),json_extract(value,'$[3]'),json_extract(value,'$[4]'),json_extract(value,'$[5]'),json_extract(value,'$[6]'),json_extract(value,'$[7]') FROM json_each('[["chunk_12ae1b4f7a612d1436c63c46","wiki/sources/ausnahme-241-ril-408-data.md",2,"Seite 2","Abschnitt 1 â€žETCS-Streckeneinrichtung gestÃ¶rtâ€œ\n\nIm letzten Satz wurden die Signale Lf 4 und Lf 5 (DV 301) gestrichen, da diese auf\n\nder Infrastruktur der DB InfraGO AG nicht mehr aufgestellt sind.\n\nAbschnitt 2 â€žETCS-Streckeneinrichtung unwirksam â€“ Anordnung der Betriebszentraleâ€œ\n\nIn Abschnitt 2 wurde der Wortlaut des Befehls im Freitext angepasst. Mit der EinfÃ¼hrung des\n\nBefehlsvordruckes im Rahmen der Neuherausgabe der Fahrdienstvorschrift wurde die Ansprache\n\ninnerhalb der AuftrÃ¤ge verÃ¤ndert. Deshalb wurde der Wortlaut â€žSchalten Sie ETCS [...] ausâ€œ\n\ngeÃ¤ndert in â€žmuss ETCS [...] ausschaltenâ€œ. AuÃŸerdem wurden bei der Zugmeldestelle die EintrÃ¤ge\n\nSeite 2 von 3\n\nErlÃ¤uterungen zur Aktualisierung 1 Ausnahme 241",100,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/11919182/f977e6b1eae42ea32f462dc0221aed65/Ausnahme-241-Ril-408-data.pdf\",\"normalized_sha256\":\"8b3e7ed459d91de5c13fbe09bbc574499e56de571af5113ef990f5c28a1255f1\",\"page\":2,\"source_id\":\"src_4eda3085c845e6a270d8\",\"source_sha256\":\"4a0808c08ae0e0ed4204e376d0336d62beb64f833b60fbdf5af73ac7a825877b\",\"source_version_id\":\"sv_894670bad1cfc26a6d5ff0e6\"}","04e87bf874fa3cded33790f69eb8c46cd5790fa1075c4a72d6c242c2ba455caa"],["chunk_6db7355b3e455e945b8c42d5","wiki/sources/ausnahme-241-ril-408-data.md",3,"Seite 3","Art und Name vorangestellt, da diese generell fÃ¼r die einzutragenden Angaben einer\n\nZugmeldestelle vorgesehen sind.\n\nWenn nach dem Ausschalten von ETCS eine Weiterfahrt mit PZB/LZB nicht mÃ¶glich ist, wurde\n\nbei den zu erteilenden Befehlen durch den Fdl der Befehl 95 mit Auftrag 95.95 ergÃ¤nzt. Im\n\nFreitext wird der Grund fÃ¼r den erteilten Befehl 5 mit GeschwindigkeitsbeschrÃ¤nkung auf 50\n\nkm/h angegeben (ETCS-Streckeneinrichtung am Hauptsignal oder Sperrsignal gestÃ¶rt). Die\n\nNotwendigkeit der Erteilung lieÃŸ sich fÃ¼r den Tf bis dato nur aus dem Beispielbefehl ableiten.\n\nDieser wurde gestrichen, da in den einzelnen Richtlinien der Richtlinienfamilie 408 keine\n\nBeispielbefehle mehr vorgesehen sind.\n\nAbschnitt 4 â€žAutomatischer Levelwechsel von ETCS-Level 1 LS nach ETCS-Level NTC\n\nPZB/LZB hat nicht stattgefundenâ€œ\n\nIn Absatz (3) wurde der Randvermerk prÃ¤zisiert und an den ETCS-Level NTC PZB/LZB angepasst.\n\nAbschnitt 7 â€žBalisenlesefehlerâ€œ und Abschnitt 8 â€žBremseingriff (Zwangsbetriebsbremsung\n\noder Zwangsbremsung) durch ETCSâ€œ\n\nDer Wortlaut fÃ¼r die Bedienung von Override EOA wurde an die Vorgaben des neuen\n\nBefehlsvordruckes angepasst.\n\nMit freundlichen GrÃ¼ÃŸen\n\nDB InfraGO AG, GeschÃ¤ftsbereich Fahrweg\n\ngez. Christian Ehrhardt gez. Ulrich HÃ¤ffner\n\nLeiter Grundlagen und Verfahren Experte Fahrdienstvorschrift\n\nBahnbetrieb\n\nSeite 3 von 3\n\nErlÃ¤uterungen zur Aktualisierung 1 Ausnahme 241",186,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/11919182/f977e6b1eae42ea32f462dc0221aed65/Ausnahme-241-Ril-408-data.pdf\",\"normalized_sha256\":\"8b3e7ed459d91de5c13fbe09bbc574499e56de571af5113ef990f5c28a1255f1\",\"page\":3,\"source_id\":\"src_4eda3085c845e6a270d8\",\"source_sha256\":\"4a0808c08ae0e0ed4204e376d0336d62beb64f833b60fbdf5af73ac7a825877b\",\"source_version_id\":\"sv_894670bad1cfc26a6d5ff0e6\"}","59304db570b192c0a50463322c905ca4eeae2285048aabef1bc5a3ad0741aeea"],["chunk_ba696a919dc6fa894425eaea","wiki/sources/ausnahme-241-ril-408-data.md",4,"Seite 4","Richtlinie\n\nBahnbetrieb Fahrdienstvorschrift\n\nZÃ¼ge fahren; UnregelmÃ¤ÃŸigkeiten an der Zugbeeinflussung - ETCS- 408.2654\n\nLevel 1 LS Seite 1\n\n1 ETCS-Streckeneinrichtung gestÃ¶rt\n\nWenn der Tf eine StÃ¶rung an der ETCS-Streckeneinrichtung feststellt oder vermutet, muss er dies dem Fdl melden.\n\nEr muss - soweit er dies feststellen kann â€“ Folgendes angeben:\n\n- das Signal, an dem sich die gestÃ¶rte Einrichtung befindet oder die Lage der\n\ngestÃ¶rten Einrichtung,\n\n- den BahnÃ¼bergang, vor dem sich die gestÃ¶rte Einrichtung befindet.\n\n* Bei gestÃ¶rter ETCS-Streckeneinrichtung an Langsamfahrstellen muss der Tf ge-\n\n* meinsam mit dem Fdl feststellen, ob sich zwischen dem Signal Lf 1 oder Lf 6 und\n\n* dem Signal Lf 2 oder Lf 7 ein Hauptsignal befindet.\n\n2 ETCS-Streckeneinrichtung unwirksam â€“ Anordnung der\n\nBetriebszentrale\n\nWenn die ETCS-Streckeneinrichtung unwirksam ist darf die Betriebszentrale anordnen, dass alle ZÃ¼ge zwischen zwei Zugmeldestellen ohne Zugbeeinflussung ETCS\n\nfahren.\n\nDer Tf muss dem Fdl mitteilen, ob er nach dem Ausschalten von ETCS mit PZB/LZB\n\nweiterfahren kann. Wenn der Tf mit PZB/LZB weiterfahren kann, erteilt ihm der Fdl\n\n* Befehl 95 mit Auftrag 95.95 mit dem Wortlaut â€žmuss ETCS von ... [Art und Name\n\n* der Zugmeldestelle] bis ... [Art und Name der Zugmeldestelle] ausschalten.â€œ\n\nWenn nach dem Ausschalten von ETCS eine Weiterfahrt mit PZB/LZB nicht mÃ¶glich\n\n* ist, erteilt der Fdl Befehle 5 und 95 mit Auftrag 95.95 wegen gestÃ¶rter ETCS-Stre-\n\n* ckeneinrichtung. Der Tf fÃ¤hrt mit eingeschalteter Zugbeeinflussung ETCS weiter.\n\n3 ETCS-Fahrzeugeinrichtung gestÃ¶rt\n\n(1) Eine StÃ¶rung an der ETCS-Fahrzeugeinrichtung muss der Tf der Betriebszentrale melden.\n\n(2) Der Tf muss dem Fdl nach dem Anhalten mitteilen, wo die Spitze des Zuges\n\nhÃ¤lt.",261,"{\"canonical_url\":\"https://www.dbinfrago.com/resource/blob/11919182/f977e6b1eae42ea32f462dc0221aed65/Ausnahme-241-Ril-408-data.pdf\",\"normalized_sha256\":\"8b3e7ed459d91de5c13fbe09bbc574499e56de571af5113ef990f5c28a1255f1\",\"page\":4,\"source_id\":\"src_4eda3085c845e6a270d8\",\"source_sha256\":\"4a0808c08ae0e